        if c == 47 && i + 1 < b.len() && b[i + 1] == 42 { i += 2; let mut bcd = 1; while i + 1 < b.len() && bcd > 0 { if b[i] == 47 && b[i + 1] == 42 { bcd += 1; i += 2; } else if b[i] == 42 && b[i + 1] == 47 { bcd -= 1; i += 2; } else { i += 1; } } continue; }   // `/* .. */` block comment -- NESTED (Rust allows `/* /* */ */`); track depth so an inner `/*` does not let the first `*/` close the outer comment early and leak the tail as unmatched tokens (compiler-builtins u128 div, E "unmatched closing delimiter")
        if c == 47 { out.push(Tok::Slash); offs.push(ts); i += 1; continue; }
        if c == 37 { out.push(Tok::Percent); offs.push(ts); i += 1; continue; }
        if c == 94 { out.push(Tok::Caret); offs.push(ts); i += 1; continue; }
        if c == 63 { out.push(Tok::Question); offs.push(ts); i += 1; continue; }   /* ? try operator */
