                let mut ci = i + 1;
                let mut k = i + 1;
                while k < n { if streq(&bt[k], "(") { d = d + 1; } if streq(&bt[k], ")") { d = d - 1; if d == 0 { ci = k; k = n; } } k = k + 1; }
                let mut inner = String::new();
                let mut j = i + 2;
                while j < ci { if inner.len() > 0 { inner.push(' '); } inner.push_str(&bt[j]); j = j + 1; }
