        // Pure as_bytes + slice-to_string (the lexer's proven idiom) -- re-lexing inside this method mis-lowered.
        let mb = m.as_bytes();
        if mb.len() < 3 { return String::from(""); }
        if mb[0] != 36 || mb[1] != 32 { return String::from(""); }
