            match self.peek() {
                Tok::Colon => { self.bump(); let ty = self.parse_ty(); params.push(Param { name: String::from("self"), ty: Box::new(ty) }); }   // explicit-typed receiver `self: Box<Self>` -> keep name=self; the ty carries the type
                _ => { let mut segs: Vec<PathSeg> = Vec::new(); segs.push(PathSeg { ident: String::from("Self"), args: Vec::new(), paren: false }); params.push(Param { name: recv, ty: Box::new(Ty::Path(Box::new(Path { segments: segs, maybe: false }))) }); }   // bare/ref receiver -> the receiver form in name, synthesized `Self`-path ty
            }
