// unrelated `cfg_target_has_reliable_f16_f128` attribute does not false-trigger. Single form `#![feature(f16)]`
// (what core uses) and the combined-list form `feature(f16, f128)`.
fn s1_scan_feats(src: &str) { unsafe {
    if str_contains(src, "feature(f16)") || str_contains(src, "feature(f16,") { S1_FEAT_F16 = 1; } else { S1_FEAT_F16 = 0; }
    if str_contains(src, "feature(f128)") || str_contains(src, ", f128)") { S1_FEAT_F128 = 1; } else { S1_FEAT_F128 = 0; }
} }
static mut S1_BYTELIT: i64 = 0;
fn s1_set_bytelit() { unsafe { S1_BYTELIT = 1; } }
fn s1_take_bytelit() -> bool { unsafe { let v = S1_BYTELIT; S1_BYTELIT = 0; v == 1 } }
static mut S1_STRKIND: i64 = 0;
fn s1_set_strkind(k: i64) { unsafe { S1_STRKIND = k; } }
