            while j < bb.len() && bb[j] != 125 {
                if bb[j] != 95 {
                    let h = esc_hexval(bb[j]);
                    if h < 0 { esc_refuse(6, ts); return; }
                    v = v * 16 + h;
                    nd += 1;
                }
                j += 1;
            }
            if j >= bb.len() { esc_refuse(7, ts); return; }
            if nd < 1 { esc_refuse(8, ts); return; }
            if nd > 6 { esc_refuse(9, ts); return; }
            if v > 1114111 { esc_refuse(10, ts); return; }
