    let op: &str = if streq(op,"sub"){"sub8"} else if streq(op,"mul"){"mul8"} else if streq(op,"lt"){"lt8"} else {op};
    if streq(op, "add") { let c = s9ak_get(a, b); if c >= 0 { return c; } let v = s9fresh(); println!("  v{}: i64 = add8 v{} v{}", v, a, b); s9ak_put(a, b, v); return v; }
    let v = s9fresh();
    if s9_op_is64(op) { println!("  v{}: i64 = {} v{} v{}", v, op, a, b); } else { println!("  v{}: i32 = {} v{} v{}", v, op, a, b); }
