// cloned()/copied() over `x.iter()` is identity for our value model: lower it as a plain iter over x. Takes
// &ExprK (r is a &Box<ExprK> at the call; the fn-arg coercion deref's it -- match &Box via a &ExprK helper, the
// rustc-valid idiom, not an inline &**r). Returns -1 when the receiver is not a bare iter (caller falls through).
fn s9_chain_cloned(e: &ExprK, tk: i32, pc: i32, pe: i32, env: &S9Env) -> i32 {
    match e { ExprK::Method(vr, rn, _rt, ra) => { if streq(rn, "iter") { if ra.len() == 0 { return s9_chain_with(vr, 0, vr, false, tk, pc, pe, env); } } if streq(rn, "rev") { if ra.len() == 0 { let rv = s9_rev_chain(vr, tk, pc, pe, env); if rv != 0 - 1 { return rv; } } } } _ => {} }
    0 - 1
}
// `<closure-iter>[.map(f)].find(p)` -> Option<Item>. The closure iterator (tokenize()/from_fn) has no Vec base,
// so s9_chain_loop's index model does not apply; the "next element" is a call of the closure (chain_call0) and the
// loop runs while it yields Some. Branchless found-flag capture of the first mapped value that satisfies p (mirrors
// s9_chain_loop tk-7, but captures the VALUE, since .map already produced it). Returns -1 if not a closure-iter find.
fn s9_clositer_find(mrecv: &ExprK, pred: &ExprK, env: &S9Env) -> i32 {
    let mut base = mrecv;
    let mut have_map = false; let mut mc = 0; let mut me = 0;
    match mrecv { ExprK::Method(inner, mn, _t, ma) => { if streq(mn, "map") && ma.len() == 1 { base = inner; let cc = s9_chain_clos_slots(&ma[0], env); mc = cc.code; me = cc.cenv; have_map = true; } }, _ => {} }
    if !s9_is_clositer(base, env) { return 0 - 1; }
    let cell = s9expr(base, env);
    let cp = s9_cell_parts(cell);
    let cs = s9fresh(); s9emit_setslot(cs, cp.code);
    let es = s9fresh(); s9emit_setslot(es, cp.cenv);
    let pcc = s9_chain_clos_slots(pred, env);
    let found = s9fresh(); let z0 = s9const(0); s9emit_setslot(found, z0);
    let best = s9fresh(); let z1 = s9const(0); s9emit_setslot(best, z1);
    s9emit_loop_open();
    let o = s9_chain_call0(cs, es);
    let tag = s9_load_at(o, 0);
    let one = s9const(1);
    let is_some = s9op("eq", tag, one);
    let one2 = s9const(1);
    let nfound = s9op("sub", one2, found);
    let guard = s9op("and", is_some, nfound);
    s9emit_brz(guard);
    let v = s9_slot_load(o, 8);
    let mapped = if have_map { s9_chain_call1(mc, me, v) } else { v };
    let keep = s9_chain_call1(pcc.code, pcc.cenv, mapped);
    let sel = s9op("mul", keep, nfound);
    let one3 = s9const(1);
    let nsel = s9op("sub", one3, sel);
    let a0 = s9op("mul8", mapped, sel);
    let a1 = s9op("mul8", best, nsel);
    let nb = s9op("add8", a0, a1);
    s9emit_setslot(best, nb);
    let nf = s9op("or", found, keep);
    s9emit_setslot(found, nf);
    s9emit_cont();
    s9emit_jmpend();
    let rvw = s9fresh(); let lw = s9_lbl();
    let z2 = s9const(0); let nz = s9op("ne", found, z2);
    s9emit_brz(nz);
    let some = s9_some_of(env, best);
    s9emit_then_tail(rvw, lw, some);
    let none = s9_enum_unit(env, "None");
    s9emit_else_tail(rvw, lw, none);
    rvw
}
fn s9_rev_vec(hdr: i32) -> i32 {
    // reverse a materialized Vec in place: swap element i and (len-1-i). Word (8-byte) elements. Branchless-safe:
    // the only control is the loop guard (i < j); no nested if-scope.
    let len = s9_load_at(hdr, 0);
    let dp = s9_slot_load(hdr, 8);
    let icell = s9_alloc(4); let z = s9const(0); s9_store_at(icell, 0, z);
    s9emit_loop_open();
    let i = s9_load_at(icell, 0);
    let one = s9const(1); let lm1 = s9op("sub", len, one); let j = s9op("sub", lm1, i);
    let g = s9op("lt", i, j); s9emit_brz(g);
    let e8 = s9const(8);
    let ia = s9op("mul", i, e8); let aa = s9op("add8", dp, ia);
    let ja = s9op("mul", j, e8); let ba = s9op("add8", dp, ja);
    let va = s9fresh(); println!("  v{}: i64 = load8 v{}", va, aa);
    let vb = s9fresh(); println!("  v{}: i64 = load8 v{}", vb, ba);
    println!("  store8 v{} v{}", aa, vb); println!("  store8 v{} v{}", ba, va);
    let i2 = s9_load_at(icell, 0); let ni = s9op("add", i2, one); s9_store_at(icell, 0, ni);
    s9emit_loop_close();
    hdr
}
fn s9_rev_chain(inner: &ExprK, tk: i32, pc: i32, pe: i32, env: &S9Env) -> i32 {
    // `<inner>.rev().<terminal>` -- an order-independent terminal ignores rev (recurse on inner); collect forward
    // then reverses the result Vec. `inner` is the pre-rev chain (e.g. `v.iter()` / `v.into_iter()`).
    if tk == 0 || tk == 1 || tk == 2 || tk == 3 || tk == 4 || tk == 5 || tk == 9 { return s9_chain_try(inner, tk, pc, pe, env); }
    if tk == 6 { let fwd = s9_chain_try(inner, 6, pc, pe, env); if fwd != 0 - 1 { return s9_rev_vec(fwd); } return 0 - 1; }
    0 - 1
}
fn s9_chain_try(mrecv: &ExprK, tk: i32, pc: i32, pe: i32, env: &S9Env) -> i32 {
    match mrecv { ExprK::Method(r0, n0, _t0, a0) => { if streq(n0, "rev") { if a0.len() == 0 { let rv = s9_rev_chain(r0, tk, pc, pe, env); if rv != 0 - 1 { return rv; } } } } _ => {} }
    match mrecv {
        ExprK::Method(r, n, _t, a) => {
            if streq(n, "iter") || streq(n, "into_iter") { if a.len() == 0 { return s9_chain_with(r, 0, r, false, tk, pc, pe, env); } }
            if streq(n, "cloned") || streq(n, "copied") { if a.len() == 0 { let cv = s9_chain_cloned(r, tk, pc, pe, env); if cv != 0 - 1 { return cv; } } }
            let ak = if streq(n, "map") { 1 } else if streq(n, "filter") { 2 } else if streq(n, "filter_map") { 3 } else { 0 - 1 };
            if ak > 0 { if a.len() == 1 { let mut out = 0 - 1;
                        for c0 in a.iter() { out = s9_chain_inner(r, ak, c0, tk, pc, pe, env); }
                        return out; } }
            0 - 1 }
        _ => 0 - 1
    }
}
fn s9_ctor_map_name(clos: &ExprK, env: &S9Env) -> String {
    // a bare constructor path used as a map fn: `Some` / `Ok` / a registered enum-variant or tuple-struct ctor.
    // Returns the ctor name (so `.map(Some)` == `.map(|x| Some(x))`), else "".
    match clos {
        ExprK::Path(p) => { let n = dump_path(p); let ls = s9_last_seg_str(&n);
            if streq(&ls, "Some") || streq(&ls, "Ok") || streq(&ls, "Err") { return ls; }
            if s9_reg_known(env, &format!("$tst#{}", ls)) { return ls; }           // tuple-struct ctor
            let e = s9_enum_seg(&n); if e.len() > 0 { if s9_field_has(env, &format!("{}#{}", e, ls)) { return ls; } }
            if s9_field_has(env, &format!("$variantenum#{}", ls)) { return ls; }    // bare-imported variant ctor
            String::new() }
        _ => String::new()
    }
}
fn s9_map_ctor_collect(vrecv: &ExprK, ctor: &str, env: &S9Env) -> i32 {
    // `<iter>.map(Ctor).collect()` -> a Vec whose i-th element is the single-payload cell Ctor(elem_i)
    // {tag@0, payload@8}. Mirrors s9_chain_loop tk=6's 8-byte-stride element walk.
    let tag = s9_enum_tag(env, ctor);
    let vbase = s9expr(vrecv, env);
    let it = s9_vec_iter_bounds(vbase);
    let hdr = s9_vec_new();
    let esl = s9fresh(); s9emit_setslot(esl, it.dptr);
    s9emit_loop_open();
    let g = s9op("lt8", esl, it.end); s9emit_brz(g);
    let raw = s9_slot_load(esl, 0);
    let cell = s9_alloc(16); let tv = s9const(tag as i64); s9_store_at(cell, 0, tv); s9_slot_store(cell, 8, raw);
    s9_vec_push1(hdr, cell);
    s9emit_cont();
    s9emit_incr4(esl);
    s9emit_jmpend();
    hdr
}
fn s9_chain_inner(itercall: &ExprK, ak: i32, clos: &ExprK, tk: i32, pc: i32, pe: i32, env: &S9Env) -> i32 {
    match itercall { ExprK::Method(vr, n, _t, a) => { if streq(n, "iter") || streq(n, "into_iter") { if a.len() == 0 {
                        if ak == 1 && tk == 6 { let cm = s9_ctor_map_name(clos, env); if cm.len() > 0 { return s9_map_ctor_collect(vr, &cm, env); } }
                        return s9_chain_with(vr, ak, clos, true, tk, pc, pe, env); } } 0 - 1 }, _ => 0 - 1 }
}
fn s9_chain_with(vrecv: &ExprK, ak: i32, clos: &ExprK, have_ad: bool, tk: i32, pc: i32, pe: i32, env: &S9Env) -> i32 {
    let mut ac = 0 - 1; let mut ae = 0 - 1;
    if have_ad { let cc = s9_chain_clos_slots(clos, env); ac = cc.code; ae = cc.cenv; }
    s9_chain_loop(vrecv, ak, ac, ae, tk, pc, pe, env)
}
fn s9_chain_call1(cs: i32, es: i32, a: i32) -> i32 {
    let r = s9fresh(); println!("  v{}: i32 = calli v{} v{} v{}", r, cs, es, a); r
}
// A 0-argument closure call (only the captured env is passed): `std::iter::from_fn(move || ...)`'s closure
// takes no user parameter and returns Option<Item>. Mirrors s9_chain_call1 without the element word.
fn s9_chain_call0(cs: i32, es: i32) -> i32 {
    let r = s9fresh(); println!("  v{}: i32 = calli v{} v{}", r, cs, es); r
}
// One loop for every (adaptor, terminal) pair. `ac`/`ae` are the adaptor closure's cell parts, `pc`/`pe` the
// terminal predicate's; either may be absent (-1), in which case that stage is skipped.
// C-S9-USER-ITER-COLLECT: `<it>.collect::<Vec<_>>()` where `it` is a USER Iterator (a struct with a `next()`
// -> Option method), as opposed to the adaptor chains s9_chain_go handles. Loop: call it.next() (mutates the
// iterator in place through its self pointer), break on the None tag (0), push the Some payload (@8) into a
// fresh Vec. rustc_parse_format's `Parser::new(..).collect::<Vec<Piece>>()` is exactly this.
fn s9_user_iter_collect_call(recv: &ExprK, tgt: &str, env: &S9Env) -> i32 {
    // Mirror the banked PATH-recv user-iter collect loop structure (s9emit_brz(tag) exits on None=0, then
    // cont/jmpend), but evaluate the CALL receiver ONCE (rb) and call next() on that same pointer -- s9_method
    // would re-emit the Parser::new(..) constructor each iteration.
    let vb = s9_vec_new();
    let rb = s9expr(recv, env);
    s9emit_loop_open();
    let opt = s9call1(tgt, rb);
    let tag = s9_load_at(opt, 0);
    s9emit_brz(tag);
    let payload = s9_slot_load(opt, 8);
    s9_vec_push1(vb, payload);
    s9emit_cont(); s9emit_jmpend();
    vb
}
fn s9_chain_loop(recv: &ExprK, ak: i32, ac: i32, ae: i32, tk: i32, pc: i32, pe: i32, env: &S9Env) -> i32 {
    let vbase = s9expr(recv, env);
    let it = s9_vec_iter_bounds(vbase);
    let esl = s9fresh(); s9emit_setslot(esl, it.dptr);
    let init = if tk == 3 || tk == 9 { s9const(1) } else { s9const(0) };
    let acc = s9fresh(); s9emit_setslot(acc, init);
    let seen = s9fresh(); let z_seen = s9const(0); s9emit_setslot(seen, z_seen);         // max/min: 0 until first element
    let acc_addr = s9fresh(); let z_addr = s9const(0); s9emit_setslot(acc_addr, z_addr); // max/min: address of the current best (returns Option<&T>)
    // collect (tk 6): pre-allocate an EXACT result Vec (map preserves count) so the per-element store needs no
    // capacity check -- __vec_grow's brz cannot live inside this branchless loop. `acc` doubles as the write index.
    let mut reshdr = 0; let mut resbuf = 0;
    if tk == 6 { let srclen = s9_load_at(vbase, 0); let f8a = s9const(8); let resbytes = s9op("mul", srclen, f8a); resbuf = s9_alloc_dyn(resbytes); reshdr = s9_alloc(16); s9_slot_store(reshdr, 8, resbuf); s9_store_at(reshdr, 4, srclen); }
    s9emit_loop_open();
    let g = s9op("lt8", esl, it.end);
    s9emit_brz(g);
    let raw = s9_slot_load(esl, 0);
    // ak==3 = filter_map: the closure returns Option<U>; call it ONCE, ev = payload@8, gv = (tag==Some) -> keep.
    let och = if ak == 3 { s9_chain_call1(ac, ae, raw) } else { s9const(0) };
    let ev = if ak == 1 { s9_chain_call1(ac, ae, raw) } else if ak == 3 { s9_slot_load(och, 8) } else { raw };
    // The guard: `filter`'s predicate, filter_map's Some-tag, the terminal's own predicate for any/all. 1 when none.
    let sm3 = s9_enum_tag(env, "Some");
    let gv = if ak == 2 { s9_chain_call1(ac, ae, ev) } else if ak == 3 { let tag = s9_load_at(och, 0); s9op("eq", tag, s9const(sm3 as i64)) } else if pc >= 0 { s9_chain_call1(pc, pe, ev) } else { s9const(1) };
    if tk == 6 { let f8s = s9const(8); let ioff = s9op("mul", acc, f8s); let addr = s9op("add8", resbuf, ioff); println!("  store8 v{} v{}", addr, ev); }
    // BRANCHLESS accumulate. A conditional inside the loop body cannot use the then_tail/else_tail shape here:
    // the trajectory records that nested if-scopes inside a loop are wrong in general, because only the
    // OUTERMOST brz is closed by `endloop` -- and the first version of this loop SIGSEGV'd on exactly that.
    // With a 0/1 guard the four terminals are arithmetic instead: sum adds ev*gv, count adds gv, `any` sums the
    // guard and clamps once at the end, `all` multiplies. No extra control flow, so no scope to mis-close.
    // max/min (tk 4/5): sel = (seen==0) | (ev is new best); best VALUE and best ADDRESS both selected branchlessly.
    // Return Option<&T>, so the ADDRESS accumulator (esl = current element address) is the result. 64-bit ops.
    let sel = if tk == 4 { let c = s9op("lt8", acc, ev); let one = s9const(1); let ns = s9op("sub", one, seen); s9op("or", ns, c) }
        else if tk == 5 { let c = s9op("lt8", ev, acc); let one = s9const(1); let ns = s9op("sub", one, seen); s9op("or", ns, c) }
        else if tk == 7 || tk == 8 { let one = s9const(1); let ns = s9op("sub", one, seen); s9op("mul", gv, ns) }
        else if tk == 10 { gv }
        else { s9const(0) };
    let step = if tk == 0 { let m = s9op("mul", ev, gv); s9op("add", acc, m) }
        else if tk == 1 { s9op("add", acc, gv) }
        else if tk == 2 { s9op("add", acc, gv) }
        else if tk == 3 { s9op("mul", acc, gv) }
        else if tk == 6 { s9op("add", acc, gv) }
        else if tk == 7 || tk == 8 || tk == 10 { s9const(0) }
        else if tk == 9 { let m = s9op("mul8", ev, gv); let one = s9const(1); let ng = s9op("sub", one, gv); let f = s9op("add8", m, ng); s9op("mul8", acc, f) }
        else { let one = s9const(1); let nsel = s9op("sub", one, sel); let a0 = s9op("mul8", ev, sel); let a1 = s9op("mul8", acc, nsel); s9op("add8", a0, a1) };
    s9emit_setslot(acc, step);
    if tk == 4 || tk == 5 {
        let one = s9const(1); let nsel = s9op("sub", one, sel);
        let b0 = s9op("mul8", esl, sel); let b1 = s9op("mul8", acc_addr, nsel); let na = s9op("add8", b0, b1);
        s9emit_setslot(acc_addr, na);
        let one2 = s9const(1); s9emit_setslot(seen, one2);
    }
    if tk == 7 || tk == 8 || tk == 10 {
        let one = s9const(1); let nsel = s9op("sub", one, sel);
        let b0 = s9op("mul8", esl, sel); let b1 = s9op("mul8", acc_addr, nsel); let na = s9op("add8", b0, b1);
        s9emit_setslot(acc_addr, na);
        let ns2 = s9op("or", seen, gv); s9emit_setslot(seen, ns2);
    }
    s9emit_cont();
    s9emit_incr4(esl);
    s9emit_jmpend();
    if tk == 2 { let z = s9const(0); return s9op("ne", acc, z); }
    if tk == 6 { s9_store_at(reshdr, 0, acc); return reshdr; }
    if tk == 7 {
        let rvw = s9fresh(); let lw = s9_lbl();
        let z0 = s9const(0); let nz = s9op("ne", seen, z0);
        s9emit_brz(nz);
        let some = s9_some_of(env, acc_addr);
        s9emit_then_tail(rvw, lw, some);
        let none = s9_enum_unit(env, "None");
        s9emit_else_tail(rvw, lw, none);
        return rvw;
    }
    // position (tk 8): the loop captured the first-match element ADDRESS into acc_addr (same as find). The
    // result is the INDEX, so convert address->index at the end: (acc_addr - dptr) / 8. Some(index) or None.
    if tk == 8 || tk == 10 {
        let off = s9op("sub8", acc_addr, it.dptr); let eight = s9const(8); let idx = s9op("div", off, eight);
        let rvw = s9fresh(); let lw = s9_lbl();
        let z0 = s9const(0); let nz = s9op("ne", seen, z0);
        s9emit_brz(nz);
        let some = s9_some_of(env, idx);
        s9emit_then_tail(rvw, lw, some);
        let none = s9_enum_unit(env, "None");
        s9emit_else_tail(rvw, lw, none);
        return rvw;
    }
    if tk == 4 || tk == 5 {
        let len = s9_load_at(vbase, 0);
        let rvw = s9fresh(); let lw = s9_lbl();
        let z0 = s9const(0);
        let nz = s9op("ne", len, z0);
        s9emit_brz(nz);
        let some = s9_some_of(env, acc);
        s9emit_then_tail(rvw, lw, some);
        let none = s9_enum_unit(env, "None");
        s9emit_else_tail(rvw, lw, none);
        return rvw;
    }
    acc
}
// `v.iter().count()` over a Vec is its LENGTH -- there is no lazy sequence here to walk, and walking one would
// only recompute len@0. Kept separate from s9_iter_sum so the shape is stated rather than implied.
// is this `<v>.iter().map(<closure>)`? returns the closure, else None-ish via the caller's guard
// `<v>.iter().map(c)` -> unwrap one level to the `.iter()` call and its closure, then one more to `<v>`.
// Each level passes a Box field to a fn taking &ExprK, which auto-derefs at the boundary; matching `&**x`
// inline does not survive L6's parser (CT-156).
fn s9_is_iter_call(e: &ExprK) -> bool { match e { ExprK::Method(_r, n, _t, a) => { if a.len() > 0 { return false; } streq(n, "iter") } _ => false } }
fn s9_is_iterish_call(e: &ExprK) -> bool { match e { ExprK::Method(_r, n, _t, a) => { if a.len() > 0 { return false; } streq(n, "iter") || streq(n, "into_iter") } _ => false } }
fn s9_rev_of_iterish(e: &ExprK) -> bool { match e { ExprK::Method(rr, rn, _t, ra) => { if streq(rn, "rev") { if ra.len() == 0 { return s9_is_iterish_call(rr); } } } _ => {} } false }   // `<iter>.rev()` as a chainable base under cloned   // iter OR into_iter (by-value) as a chain source
// C-S9-VEC-POP: `v.pop()` returned nothing and removed nothing -- `match v.pop()` gave 0 with the length
// unchanged, while L6 is correct. It is the dominant `while let` scrutinee in the corpus (10 of 14 files use
