// `v.last()` -> Some(&v[len-1]) when the length is non-zero, else None. Mirror of s9_vec_first from the other
// end: Option<&T>, payload = address dptr + (len-1)*8. Direct-slice/iter only (no adaptor chain, like first).
fn s9_vec_last(base: i32, env: &S9Env) -> i32 {
    let rv = s9fresh();
    let lbl = s9_lbl();
    let len = s9_load_at(base, 0);
    let zero = s9const(0);
    let nz = s9op("ne", len, zero);
    s9emit_brz(nz);
    let dp = s9_slot_load(base, 8);
    let one = s9const(1);
    let lm1 = s9op("sub", len, one);
    let eight = s9const(8);
    let off = s9op("mul", lm1, eight);
    let addr = s9op("add8", dp, off);
    let some = s9_some_of(env, addr);
    s9emit_then_tail(rv, lbl, some);
    let none = s9_enum_unit(env, "None");
    s9emit_else_tail(rv, lbl, none);
    rv
}
// `o.unwrap_or(d)` -> the payload when the tag is the Some tag, else `d`. Option only (Some=1); a Result
// receiver would need the Ok=0 tag, and `unwrap_or` on Result is not yet distinguished -- recorded, not built.
// The tag is a PARAMETER now, not the constant 1: Some=1, Ok=0. Everything else about the lowering is
// identical, which is why this was one constant rather than a second builtin.
fn s9_unwrap_tag(env: &S9Env, recv: &ExprK) -> i32 {
    let rty = s9_recv_vty(env, recv);
    if str_contains(&rty, "Result") { return 0; }
    let rit = s9_init_ty(env, recv);
    if str_contains(&rit, "Result") { return 0; }
    1
}
fn s9_opt_unwrap_or_t(base: i32, dflt: i32, want: i32) -> i32 {
    let rv = s9fresh();
    let lbl = s9_lbl();
    let tag = s9_load_at(base, 0);
    let one = s9const(want as i64);
    let is_some = s9op("eq", tag, one);
    s9emit_brz(is_some);
    let pay = s9_slot_load(base, 8);
    s9emit_then_tail(rv, lbl, pay);
    s9emit_else_tail(rv, lbl, dflt);
    rv
}
// `o.unwrap_or_else(|| E)` -> payload when Some, else evaluate the closure body LAZILY in the else branch (E must
// NOT run when Some). Zero-arg closure: its body's free names are the enclosing env's, so it inlines directly with
// no closure ABI. Distinct from unwrap_or (kind 11), whose default is EAGER.
fn s9_unwrap_or_else(base: i32, args: &Vec<ExprK>, want: i32, env: &S9Env) -> i32 {
    let rv = s9fresh();
    let lbl = s9_lbl();
    let tag = s9_load_at(base, 0);
    let one = s9const(want as i64);
    let is_some = s9op("eq", tag, one);
    s9emit_brz(is_some);
    let pay = s9_slot_load(base, 8);
    s9emit_then_tail(rv, lbl, pay);
    let mut ev = 0;
    for a in args.iter() {
        match a {
            ExprK::Closure(_m, _p, _r, body) => { ev = s9expr(body, env); },
            _ => { ev = s9expr(a, env); },
        }
    }
    s9emit_else_tail(rv, lbl, ev);
    rv
}
// IDENTITY string methods in the flat model (a &str IS the String inline [len@0,bytes@4+] layout): `.to_string()`/`.to_owned()`
// /`.as_str()`/`.as_ref()` return the receiver value unchanged. Kept as a SEPARATE small predicate + an early return in
// s9_method (NOT added to s9_method_kind's if-else chain, which L6 mis-compiles once it grows past ~10 arms -- that lengthening
// made as_bytes fall through to a generic call in the L6 build only, breaking self-emit byte-identity). C-G2D-NONMAIN-AGGREGATE-METHOD.
fn s9_str_ident_m(name: &str) -> bool { streq(name, "to_string") || streq(name, "to_owned") || streq(name, "as_str") || streq(name, "as_ref") || streq(name, "into_bytes") }
// The variable name behind `&mut X` / `&X` / `X` (the lvalue target of read_to_string).
fn s9_ref_target_name(e: &ExprK) -> String {
    match e {
        ExprK::Ref(_m, inner) => s9_bare_name(inner),
        ExprK::RawRef(_m, inner) => s9_bare_name(inner),
        ExprK::Path(p) => dump_path(p),
        _ => String::from(""),
    }
}
fn s9_cell_set(b: i32, args: &Vec<ExprK>, env: &S9Env) -> i32 { for a in args.iter() { let v = s9expr(a, env); s9_slot_store(b, 0, v); } s9const(0) }
fn s9_cell_replace(b: i32, args: &Vec<ExprK>, env: &S9Env) -> i32 { let old = s9_slot_load(b, 0); for a in args.iter() { let v = s9expr(a, env); s9_slot_store(b, 0, v); } old }
fn s9_is_field_expr(e: &ExprK) -> bool { match e { ExprK::Field(_r, _n) => true, _ => false } }
fn s9_ty_is_ref(t: &str) -> bool { let b = t.as_bytes(); if b.len() > 0 { if b[0] == 38 { return true; } } if str_contains(t, "Ty Ref") { return true; } false }
fn s9_cell_base(recv: &ExprK, env: &S9Env) -> i32 { let b = s9expr(recv, env); let t = s9_recv_vty(env, recv); if s9_ty_is_ref(&t) { let d = s9fresh(); println!("  v{}: i64 = load8 v{}", d, b); d } else { b } }
fn s9_recv_is_cell(recv: &ExprK, env: &S9Env) -> bool { let t = s9_recv_vty(env, recv); if str_contains(&t, "celltype") { return true; } if str_contains(&t, "Cell<") { return true; } if str_contains(&t, "RefCell<") { return true; } false }
fn s9_str_pfxsfx(recv: &ExprK, args: &Vec<ExprK>, is_end: bool, env: &S9Env) -> i32 {   // merged starts_with/ends_with (dedup shrink -- banked headroom)
    let vr = s9expr(recv, env);
    let vn = s9expr(&args[0], env);
    let hlen = s9_load_at(vr, 0);
    let hp0 = s9_slot_load(vr, 8);
    let nlen = s9_load_at(vn, 0);
    let np = s9_slot_load(vn, 8);
    let rv = s9fresh();
    let lbl = s9_lbl();
    let bad = s9op("gt", nlen, hlen);
    s9emit_brz(bad);
    let z = s9const(0);
    s9emit_then_tail(rv, lbl, z);
    let hp = if is_end { let off = s9op("sub", hlen, nlen); s9op("add", hp0, off) } else { hp0 };
    let eq = s9call3("__streq_at", hp, np, nlen);
    s9emit_else_tail(rv, lbl, eq);
    rv
}
// `h.starts_with(n)`: n is a prefix of h. Reuses the emitted __streq_at byte-loop (as str `==` does), guarded by
// nlen <= hlen (else the compare would read past h's buffer). Both operands are String headers [len@0, dataptr@8].
// `h.starts_with(c)` / `h.ends_with(c)` with a CHAR arg: s9expr(arg) is the codepoint VALUE, not a String
// header, so the str-arg path (which s9_load_at's the arg as [len,dataptr]) segfaults. Compare a single byte
// (SEM0's ASCII char model): first byte for starts_with, last byte for ends_with, guarded by non-empty.
fn s9_str_pfxsfx_char(recv: &ExprK, arg: &ExprK, is_end: bool, env: &S9Env) -> i32 {   // merged starts/ends_with_char (dedup shrink -- banked headroom)
    let vr = s9expr(recv, env);
    let cv = s9expr(arg, env);
    let hlen = s9_load_at(vr, 0);
    let hp = s9_slot_load(vr, 8);
    let rv = s9fresh(); let lbl = s9_lbl();
    let z = s9const(0);
    let empty = s9op("eq", hlen, z);
    s9emit_brz(empty);
    s9emit_then_tail(rv, lbl, z);
    let addr = if is_end { let one = s9const(1); let off = s9op("sub", hlen, one); s9op("add8", hp, off) } else { hp };
    let b = s9_loadb(addr);
    let eq = s9op("eq", b, cv);
    s9emit_else_tail(rv, lbl, eq);
    rv
}
// SLF-CLOSE-6: `T::try_from(v)` for an integer target -> Ok(v) when v <= max(T), else Err(unit). Source is
