fn s9_try_from(cn: &str, args: &Vec<ExprK>, env: &S9Env) -> i32 {
    let ty = s9_enum_seg(cn);
    let mx = s9_int_max_of(&ty);
    let v = s9expr(&args[0], env);
    let rv = s9fresh(); let lbl = s9_lbl();
    let m = s9const(mx);
    let ok = s9op("le", v, m);
    s9emit_brz(ok);
    let okv = s9_ok_of(env, v);
    s9emit_then_tail(rv, lbl, okv);
    let z = s9const(0);
    let errv = s9_err_of(env, z);
    s9emit_else_tail(rv, lbl, errv);
    rv
}
fn s9_ok_of(env: &S9Env, v: i32) -> i32 { let tag = s9_enum_tag(env, "Ok"); let base = s9_alloc(16); let tv = s9const(tag as i64); s9_store_at(base, 0, tv); s9_slot_store(base, 8, v); base }
fn s9_err_of(env: &S9Env, v: i32) -> i32 { let tag = s9_enum_tag(env, "Err"); let base = s9_alloc(16); let tv = s9const(tag as i64); s9_store_at(base, 0, tv); s9_slot_store(base, 8, v); base }
