    let one = s9const(1);
    let issome = s9op("eq", tag, one);
    let rv = s9fresh();
    let lbl = s9_lbl();
    s9emit_brz(issome);
    let payload = s9_slot_load(base, 8);
    let mapped = s9_chain_call1(cell.code, cell.cenv, payload);
    s9emit_then_tail(rv, lbl, mapped);
    s9emit_else_tail(rv, lbl, dflt);
