    if !uc && streq(name, "is_ascii_whitespace") { let cv = s9expr(recv, env); let sp = s9op("eq", cv, s9const(32)); let tb = s9op("eq", cv, s9const(9)); let nl = s9op("eq", cv, s9const(10)); let cr = s9op("eq", cv, s9const(13)); let a = s9op("or", sp, tb); let b = s9op("or", nl, cr); return s9op("or", a, b); }
