    if streq(name, "div_euclid") { let av = s9expr(recv, env); let nv = s9expr(&args[0], env); let r = s9op("mod8", av, nv); let rn = s9op("add8", r, nv); let re = s9op("mod8", rn, nv); let d = s9op("sub8", av, re); return s9op("div8", d, nv); }
    if streq(name, "abs_diff") { let av = s9expr(recv, env); let bv = s9expr(&args[0], env); let rv = s9fresh(); let lbl = s9_lbl(); let c = s9op("gt", av, bv); s9emit_brz(c); let d1 = s9op("sub8", av, bv); s9emit_then_tail(rv, lbl, d1); let d2 = s9op("sub8", bv, av); s9emit_else_tail(rv, lbl, d2); return rv; }
    if streq(name, "signum") { let av = s9expr(recv, env); let pos = s9op("gt", av, s9const(0)); let neg = s9op("lt", av, s9const(0)); return s9op("sub8", pos, neg); }
    if streq(name, "clamp") { let av = s9expr(recv, env); let lo = s9expr(&args[0], env); let hi = s9expr(&args[1], env); let rv1 = s9fresh(); let l1 = s9_lbl(); let c1 = s9op("gt", av, lo); s9emit_brz(c1); s9emit_then_tail(rv1, l1, av); s9emit_else_tail(rv1, l1, lo); let rv2 = s9fresh(); let l2 = s9_lbl(); let c2 = s9op("lt", rv1, hi); s9emit_brz(c2); s9emit_then_tail(rv2, l2, rv1); s9emit_else_tail(rv2, l2, hi); return rv2; }
    // L6 LANDMINE, measured twice on this rung. The new kinds were first APPENDED to s9_method_kind's else-if
    // chain (9 arms -> 11); L6 drops arms past ~10, so an L6-built parser stopped recognising `pop`. Moving them
    // into a helper called from the TOP of s9_method_kind did not fix it either -- an early `return` in front of
    // that expression-position chain is mis-compiled the same way. Both broke `g2 != g3` in `parse_ty_inner`, at
    // a `.pop()` call this change should never have touched. s9_method_kind is therefore left EXACTLY as it was
    // and the new kinds are consulted here, at the call site, where no chain is extended and no return is added.
    // SLF-CLOSE-6: Result::is_ok / is_err -- unimplemented (only is_some/is_none existed), so `res.is_ok()` lowered
    // to a DANGLING `call is_ok` (harmless by luck in tiny programs, a segfault at crate scale). tag@0 == Ok's tag.
    if streq(name, "is_ok") { let rslot = s9expr(recv, env); let t = s9_load_at(rslot, 0); let ok = s9_enum_tag(env, "Ok"); return s9op("eq", t, s9const(ok as i64)); }
    if streq(name, "is_err") { let rslot = s9expr(recv, env); let t = s9_load_at(rslot, 0); let ok = s9_enum_tag(env, "Ok"); return s9op("ne", t, s9const(ok as i64)); }
    if streq(name, "get") { let vt = s9_recv_vty(env, recv); if str_contains(&vt, "Vec") { return s9_vec_get(recv, args, env); } }
    if (streq(name, "cloned") || streq(name, "copied")) && args.len() == 0 { let rt = s9_recv_vty(env, recv); let rti = s9_init_ty(env, recv); if str_contains(&rt, "Option") || str_contains(&rti, "Option") { return s9expr(recv, env); } }   // Option::cloned/copied on Option<&T>: identity in the flattened model (get() already returns the element value, C-VECGET-DEREF)
    let mut kind = s9_method_kind(name);
