    // pos (the byte index before decode) into the first binder. For SEM0's ASCII char model each char is 1 byte,
    // so the byte offset equals the char position.
    let iname = s9_pat_nth_bind(pat, 0);
    let cname = s9_pat_nth_bind(pat, 1);
