// `for i in (lo..hi).rev()` / `(lo..=hi).rev()`: count DOWN. Start at hi-1 (exclusive) or hi (inclusive),
// continue while i >= lo (g = 1 - lt8(i,lo)), decrement by 1. Range var typed i64 (RP-LOOPCLOBBER). Signed
// i64 so the i<lo exit is correct even at lo=0 (i reaches -1). Needs a finite hi.
fn s9_for_range_rev(pat: &Pat, lo: &Option<P<ExprK>>, hi: &Option<P<ExprK>>, incl: bool, body: &Block, env: &S9Env) -> i32 {
    let losl = match lo { Some(e) => s9expr(e, env), None => s9const(0) };
    let hisl = match hi { Some(e) => s9expr(e, env), None => s9const(0) };
    let one0 = s9const(1);
    let start = if incl { let f = s9fresh(); println!("  v{}: i64 = or8 v{} v{}", f, hisl, hisl); f } else { s9op("sub8", hisl, one0) };
    let isl = s9fresh(); println!("  v{}: i64 = or8 v{} v{}", isl, start, start);
    let nm = s9_patname(pat);
    let benv = s9_env_push1(env, nm, isl, String::from("i64"));
    s9emit_loop_open();
    let lt = s9op("lt8", isl, losl); let one = s9const(1); let g = s9op("sub", one, lt); s9emit_brz(g);
    s9_walk(body, &benv);
    s9emit_cont();
    let one2 = s9const(1); let dec = s9op("sub8", isl, one2); s9emit_setslot(isl, dec);
    s9emit_jmpend();
    s9const(0)
}
// `for i in (lo..hi).step_by(n)` / `(lo..=hi)`: forward range with stride n. i=lo; while i<hi (or i<=hi for
// inclusive); i+=n. n is the step arg (a positive int). Range var typed i64.
fn s9_for_range_step(pat: &Pat, lo: &Option<P<ExprK>>, hi: &Option<P<ExprK>>, incl: bool, step: &ExprK, body: &Block, env: &S9Env) -> i32 {
    let losl = match lo { Some(e) => s9expr(e, env), None => s9const(0) };
    let hisl = match hi { Some(e) => s9expr(e, env), None => s9const(0) };
    let stepv = s9expr(step, env);
    let isl = s9fresh(); println!("  v{}: i64 = or8 v{} v{}", isl, losl, losl);
    let nm = s9_patname(pat);
    let benv = s9_env_push1(env, nm, isl, String::from("i64"));
    s9emit_loop_open();
    let cmp = if incl { "le" } else { "lt" };
    let g = s9op(cmp, isl, hisl); s9emit_brz(g);
    s9_walk(body, &benv);
    s9emit_cont();
    let ni = s9op("add8", isl, stepv); s9emit_setslot(isl, ni);
    s9emit_jmpend();
    s9const(0)
}
// dispatch `(range).step_by(n)` in a for-loop: recv is &ExprK, match the Range (Paren-unwrapped).
fn s9_for_step(recv: &ExprK, step: &ExprK, pat: &Pat, body: &Block, env: &S9Env) -> i32 {
    match recv { ExprK::Range(lo, hi, incl) => s9_for_range_step(pat, lo, hi, *incl, step, body, env), ExprK::Paren(inner) => s9_for_step(inner, step, pat, body, env), _ => 0 - 1 }
}
// `for x in v.iter().rev()`: backward Vec walk. esl is the element ADDRESS, starting at the last element
// (dp+(len-1)*8), stepping DOWN by 8 while esl >= dp. Binding mirrors s9_for_iter (scalar/aggregate via
// s9_iter_bind + the Ty Ref/iterscalar element type).
fn s9_for_iter_rev(pat: &Pat, vr: &ExprK, body: &Block, env: &S9Env) -> i32 {
    let vty = s9_recv_vty(env, vr);
    let inm = s9_patname(pat);
    let ek = if vty.len() == 0 && s9_body_reads_field(body, &inm) { 0 } else { s9_vec_elem_kind(&vty) };
    let vbase = s9expr(vr, env);
    let len = s9_load_at(vbase, 0); let dp = s9_slot_load(vbase, 8);
    let one0 = s9const(1); let lm1 = s9op("sub", len, one0); let e8 = s9const(8); let off0 = s9op("mul", lm1, e8); let start = s9op("add8", dp, off0);
    let esl = s9fresh(); s9emit_setslot(esl, start);
    let evl = s9fresh(); s9emit_setslot(evl, esl);
    let ib = s9_iter_bind(ek, esl, evl);
    let isref = s9_pat_is_ref(pat);
    let bslot = if isref && ek == 1 { evl } else { ib.slot };
    let es = s9_struct_of_ty(&vty);
    let etystr = if isref && ek == 1 { String::from("") } else { if ib.refty != 0 { if streq(&es, "Vec") || es.len() == 0 { String::from("Ty Ref") } else { format!("Ty Ref(Ty Path {})", es) } } else { String::from("iterscalar") } };
    let nm = s9_patname(pat);
    let benv = s9_env_push1(env, nm, bslot, etystr);
    s9emit_loop_open();
    let lt = s9op("lt8", esl, dp); let one = s9const(1); let g = s9op("sub", one, lt); s9emit_brz(g);
    let ev = s9_slot_load(esl, 0); s9emit_setslot(evl, ev);
    s9_walk(body, &benv);
    s9emit_cont();
    let e8b = s9const(8); let dec = s9op("sub8", esl, e8b); s9emit_setslot(esl, dec);
    s9emit_jmpend();
    s9const(0)
}
// dispatch `(range).rev()` in a for-loop: recv is &ExprK (Box coercion), match the Range. -1 -> not a range rev.
fn s9_for_rev(recv: &ExprK, pat: &Pat, body: &Block, env: &S9Env) -> i32 {
    match recv { ExprK::Range(lo, hi, incl) => s9_for_range_rev(pat, lo, hi, *incl, body, env), ExprK::Paren(inner) => s9_for_rev(inner, pat, body, env), ExprK::Method(vr, n, _t, a) => { if streq(n, "iter") { if a.len() == 0 { return s9_for_iter_rev(pat, vr, body, env); } } 0 - 1 }, _ => 0 - 1 }
}
// `for x in <closure iterator>`: the iterator IS a closure value (a cell {code@0, cenv@4}) whose `.next()` is a
// call of that closure returning Option<Item>. This is `std::iter::from_fn(move || ..)` and any fn returning it
// (rustc_lexer's `tokenize` -> `from_fn(move || cursor.advance_token()..)`). Emit: loop { o = clos(); if o is not
// Some break; bind x = payload; body }. The cell is read ONCE before the loop -- cenv is a stable pointer the
// closure mutates in place across calls, exactly as the captured state must persist.
fn s9_for_clositer(pat: &Pat, iter: &ExprK, body: &Block, env: &S9Env) -> i32 {
    let cell = s9expr(iter, env);
    let cp = s9_cell_parts(cell);
    let cs = s9fresh(); s9emit_setslot(cs, cp.code);
    let es = s9fresh(); s9emit_setslot(es, cp.cenv);
    let xsl = s9fresh(); let z0 = s9const(0); s9emit_setslot(xsl, z0);
    let nm = s9_patname(pat);
    let benv = s9_env_push1(env, nm, xsl, String::from(""));
    s9emit_loop_open();
    let o = s9_chain_call0(cs, es);
    let tag = s9_load_at(o, 0);
    let one = s9const(1);
    let g = s9op("eq", tag, one); s9emit_brz(g);
    let pv = s9_slot_load(o, 8); s9emit_setslot(xsl, pv);
    s9_walk(body, &benv);
    s9emit_cont();
    s9emit_jmpend();
    s9const(0)
}
// Is the for-iterator a closure iterator (per s9_for_clositer)? `from_fn(..)` directly, a local recorded as
// "closureiter" (s9_init_ty marks from_fn that way), or a call of a fn whose return type text is an impl-Iterator.
fn s9_is_clositer(iter: &ExprK, env: &S9Env) -> bool {
    match iter {
        ExprK::Call(callee, _a) => { let cn = s9_callee_name(callee); if streq(&s9_last_seg_str(&cn), "from_fn") { return true; } let rt = s9_fn_ret_type(env, &cn); str_contains(&rt, "Impl(") && str_contains(&rt, "Iterator") }
        ExprK::Path(p) => { let nm = dump_path(p); let t = s9_lookup_type(env, &nm); str_contains(&t, "closureiter") }
        _ => false
    }
}
fn s9_for_map_kv(pat: &Pat, mrecv: &ExprK, body: &Block, env: &S9Env) -> i32 {
    // `for (k,v) in &m` / `m.iter()`: walk the parallel keys/vals Vecs, bind the tuple pattern (k,v).
    let cell = s9expr(mrecv, env);
    let kv = s9_load_at(cell, 0);
    let vv = s9_slot_load(cell, 8);
    let kn = s9_pat_nth_bind(pat, 0);
    let vn = s9_pat_nth_bind(pat, 1);
    let ksl = s9fresh(); let z0 = s9const(0); s9emit_setslot(ksl, z0);
    let vsl = s9fresh(); let z1 = s9const(0); s9emit_setslot(vsl, z1);
    let e1 = s9_env_push1(env, kn, ksl, String::from(""));
    let benv = s9_env_push1(&e1, vn, vsl, String::from(""));
    let icell = s9_alloc(4); let z2 = s9const(0); s9_store_at(icell, 0, z2);
    s9emit_loop_open();
    let i = s9_load_at(icell, 0);
    let len = s9_load_at(kv, 0);
    let cond = s9op("lt", i, len); s9emit_brz(cond);
    let e8 = s9const(8); let off = s9op("mul", i, e8);
    let kdp = s9_slot_load(kv, 8); let kaddr = s9op("add8", kdp, off); let k = s9_slot_load(kaddr, 0); s9emit_setslot(ksl, k);
    let e8b = s9const(8); let offb = s9op("mul", i, e8b);
    let vdp = s9_slot_load(vv, 8); let vaddr = s9op("add8", vdp, offb); let v = s9_slot_load(vaddr, 0); s9emit_setslot(vsl, v);
    s9_walk(body, &benv);
    let i2 = s9_load_at(icell, 0); let one = s9const(1); let ni = s9op("add", i2, one); s9_store_at(icell, 0, ni);
    s9emit_loop_close();
    s9const(0)
}
fn s9_for_map_single(pat: &Pat, mrecv: &ExprK, body: &Block, env: &S9Env, celloff: i32) -> i32 {
    // `for k in m.keys()` (celloff 0) / `for v in m.values()` (celloff 8): walk one sub-Vec.
    let cell = s9expr(mrecv, env);
    let sv = s9_load_at(cell, celloff);
    let nm = s9_patname(pat);
    let esl = s9fresh(); let z0 = s9const(0); s9emit_setslot(esl, z0);
    let benv = s9_env_push1(env, nm, esl, String::from(""));
    let icell = s9_alloc(4); let z2 = s9const(0); s9_store_at(icell, 0, z2);
    s9emit_loop_open();
    let i = s9_load_at(icell, 0);
    let len = s9_load_at(sv, 0);
    let cond = s9op("lt", i, len); s9emit_brz(cond);
    let e8 = s9const(8); let off = s9op("mul", i, e8);
    let dp = s9_slot_load(sv, 8); let addr = s9op("add8", dp, off); let e = s9_slot_load(addr, 0); s9emit_setslot(esl, e);
    s9_walk(body, &benv);
    let i2 = s9_load_at(icell, 0); let one = s9const(1); let ni = s9op("add", i2, one); s9_store_at(icell, 0, ni);
    s9emit_loop_close();
    s9const(0)
}
fn s9_for(pat: &Pat, iter: &ExprK, body: &Block, env: &S9Env) -> i32 {
    let isrv = s9_for_is_rangeval(iter, env);
    match iter {
        ExprK::Range(lo, hi, incl) => {
            let losl = match lo { Some(e) => s9expr(e, env), None => s9const(0) };
            let hisl = match hi { Some(e) => s9expr(e, env), None => s9const(0) };
            let isl = s9fresh(); println!("  v{}: i64 = or8 v{} v{}", isl, losl, losl);
            let nm = s9_patname(pat);
            let mut bn: Vec<String> = veccopy(&env.names); bn.push(nm);
            let mut bs: Vec<i32> = veccopy_i32(&env.slots); bs.push(isl);
            let mut bt: Vec<String> = veccopy(&env.types); bt.push(String::from("i64"));   // range-loop var is an integer scalar (RP-LOOPCLOBBER)
            let benv = S9Env { names: bn, slots: bs, fnames: veccopy(&env.fnames), foffs: veccopy_i32(&env.foffs), ftypes: veccopy(&env.ftypes), frets_name: veccopy(&env.frets_name), frets_ty: veccopy(&env.frets_ty), types: bt };
            s9emit_loop_open();
            let cmp = if *incl { "le" } else { "lt" };
            let g = s9op(cmp, isl, hisl); s9emit_brz(g);
            s9_walk(body, &benv);
            s9emit_cont();
            s9emit_incr(isl);
            s9emit_jmpend();
            s9const(0)
        }
        ExprK::Method(recv, mname, _mtys, _margs) => { if streq(mname, "iter") && s9_is_map_recv(env, recv) { if s9_map_is_set(env, recv) { s9_for_map_single(pat, recv, body, env, 0) } else { s9_for_map_kv(pat, recv, body, env) } } else if (streq(mname, "iter_mut")) && s9_is_map_recv(env, recv) { s9_for_map_kv(pat, recv, body, env) } else if streq(mname, "keys") && s9_is_map_recv(env, recv) { s9_for_map_single(pat, recv, body, env, 0) } else if streq(mname, "values") && s9_is_map_recv(env, recv) { s9_for_map_single(pat, recv, body, env, 8) } else if streq(mname, "iter") { s9_for_iter(pat, recv, body, env, false) } else if streq(mname, "into_iter") { s9_for_iter(pat, recv, body, env, true) } else if streq(mname, "enumerate") { s9_for_enum(pat, recv, body, env) } else if streq(mname, "chars") { s9_for_chars(pat, recv, body, env) } else if streq(mname, "bytes") && _margs.len() == 0 && s9_is_str_expr(env, recv) { s9_for_bytes(pat, recv, body, env) } else if streq(mname, "char_indices") { s9_for_char_indices(pat, recv, body, env) } else if streq(mname, "split") && _margs.len() == 1 && s9_is_lit_pat(&_margs[0]) && s9_is_str_expr(env, recv) { s9_for_split(pat, recv, &_margs[0], body, env) } else if streq(mname, "rsplit") && _margs.len() == 1 && s9_is_lit_pat(&_margs[0]) && s9_is_str_expr(env, recv) { s9_for_rsplit(pat, recv, &_margs[0], body, env) } else if streq(mname, "split_whitespace") && _margs.len() == 0 && s9_is_str_expr(env, recv) { s9_for_split_ws(pat, recv, body, env) } else if streq(mname, "lines") && _margs.len() == 0 && s9_is_str_expr(env, recv) { s9_for_lines(pat, recv, body, env) } else if streq(mname, "skip") && _margs.len() == 1 && s9_is_iter_call(recv) { s9_for_skip(pat, recv, &_margs[0], body, env) } else if streq(mname, "take") && _margs.len() == 1 && s9_is_iter_call(recv) { s9_for_take(pat, recv, &_margs[0], body, env) } else if streq(mname, "filter") && _margs.len() == 1 && s9_is_iter_call(recv) { s9_for_filter(pat, recv, &_margs[0], body, env) } else if streq(mname, "map") && _margs.len() == 1 && s9_is_iter_call(recv) { s9_for_map(pat, recv, &_margs[0], body, env) } else if streq(mname, "zip") && _margs.len() == 1 { s9_for_zip(pat, recv, &_margs[0], body, env) } else if streq(mname, "windows") && _margs.len() == 1 { let rvt = s9_recv_vty(env, recv); if str_contains(&rvt, "Vec") { s9_for_windows(pat, recv, &_margs[0], body, env) } else { s9const(0) } } else if streq(mname, "chunks") && _margs.len() == 1 { let rvt = s9_recv_vty(env, recv); if str_contains(&rvt, "Vec") { s9_for_chunks(pat, recv, &_margs[0], body, env) } else { s9const(0) } } else if streq(mname, "step_by") && _margs.len() == 1 { let sv = s9_for_step(recv, &_margs[0], pat, body, env); if sv != 0 - 1 { sv } else { s9const(0) } } else if streq(mname, "rev") && _margs.len() == 0 { let rv = s9_for_rev(recv, pat, body, env); if rv != 0 - 1 { rv } else { s9const(0) } } else if streq(mname, "escape_default") && _margs.len() == 0 { s9_for_escdefault(pat, recv, body, env) } else { s9const(0) } }
        // `for x in &v` / `&mut v`: rustc's IntoIterator for &Vec desugars to v.iter() -- iterate the referent.
        ExprK::Ref(_m, inner) => { if s9_is_map_recv(env, inner) { if s9_map_is_set(env, inner) { s9_for_map_single(pat, inner, body, env, 0) } else { s9_for_map_kv(pat, inner, body, env) } } else { s9_for_iter(pat, inner, body, env, false) } }
        // P-RANGE-EXPR, the second consumer of the cell: `let r = 0..4; for i in r`. The arm above is the INLINE
        // form and stays as it is -- it needs no allocation and is the common case. This one loads lo/hi/incl
        // back out of a range VALUE, which is why the flag is stored rather than baked in. Inclusive is folded
        // into the bound (`hi + incl`) so the comparison stays a static `lt` instead of becoming dynamic.
        _ => { if s9_is_clositer(iter, env) { s9_for_clositer(pat, iter, body, env) } else if isrv { s9_for_rangeval(pat, iter, body, env) } else { s9const(0) } }
    }
}
// the receiver Vec's declared type text (for element-kind classification): a Path local's type, or a `x.f` field's type.
fn s9_recv_vty(env: &S9Env, recv: &ExprK) -> String { match recv { ExprK::Path(p) => { let nm = dump_path(p); s9_lookup_type(env, &nm) } ExprK::Field(o, f) => { let sty = s9_recv_struct(o, env); s9_field_type_q(env, &sty, f) } ExprK::Index(arr, _ix) => { let an = s9_bare_name(arr); let at = s9_lookup_type(env, &an); s9_vec_elem_ty(&at) } _ => String::from("") } }   // SR-2: a `x.f.iter()` receiver's Vec type by the qualified field (C-G2D-FIELD-COLLISION: PathSeg.args:Vec<Ty> vs Attr.args:String)
// the element binding-kind of a `Vec<INNER>` type text: extract INNER (after the FIRST `Vec<`) and classify it (s9_ty_kind:
// 1 SCALAR i*/u*/bool, 0 aggregate String/Vec/user-struct, 2 Box). Default 1 (scalar) when no `Vec<` is found -> unchanged
// behavior for an unknown receiver. Classifying the WHOLE `Vec<..>` text would wrongly hit "Vec" -> 0; we skip past `Vec<`.
fn s9_vec_elem_kind(vty: &str) -> i32 { let b = vty.as_bytes(); let mut i = 0; let mut cut = -1; while i + 3 < b.len() { if cut < 0 { if b[i] == 86 { if b[i+1] == 101 { if b[i+2] == 99 { if b[i+3] == 60 { cut = (i as i32) + 4; } } } } } i += 1; } if cut < 0 { return 1; } let inner = &vty[(cut as usize)..]; s9_ty_kind(inner) }
// pick the loop-var binding + its by-ref flag: a SCALAR element (ek==1) binds `e` to the slot ADDRESS (esl) so a body `*e`
// loads it; an AGGREGATE element (String/Vec/struct/enum, ek 0/2) binds `e` to the slot VALUE (evl = load(esl)) = the
// element's stored address, so bare `e` (dump(e), e.len(), match e) is the aggregate. `.iter()` yields `&T`, so an aggregate
// binding IS a reference -- refty=1 records "Ty Ref" (via s9_iter_refty) so a `match e` on an enum element binds its payload
// BY-REF (`*x` loads), not by-value (which would deref the payload VALUE -> segv). `ek` is read exactly ONCE (a fn param).
struct S9IterB { slot: i32, refty: i32 }
fn s9_iter_bind(ek: i32, esl: i32, evl: i32) -> S9IterB { if ek == 1 { S9IterB { slot: esl, refty: 0 } } else { S9IterB { slot: evl, refty: 1 } } }
// the recorded type text of the loop binding: "Ty Ref" for an aggregate element (so s9_scrut_by_ref sees a reference), else "".
// `for e in v.iter()` -> pointer walk: esl (the element slot ADDRESS) steps by 4 bytes/iter while esl < end. ONE mutable slot
// (esl, like Range's isl); the bounds are FIELD reads (it.dptr/it.end) so this stays within L6's move-check budget. Each
// iteration ALSO refreshes evl = load(esl) (the element VALUE) -- always emitted (harmless dead vreg for scalars) so the only
// type-dependent branch is the ONE `ek` read in s9_pick_iter_slot, never a per-iteration conditional emit. Scalar element:
// bind esl, body `*e` loads. Aggregate element: bind evl (the stored aggregate address) so bare `e` is the aggregate. This is
// the type-aware dual of the s9_bind_slot enum-payload binding (C-G2D-VECITER-ELEMENT-KIND -- the gen2 dump-path fix).
// C-S9-VECITER-UNTYPED-ELEM (CT-156): `let ps = vec![P { v: 4 }]; for p in ps.iter() { p.v }` read a raw
// pointer. s9_for_iter picks the loop binding from the receiver's RECORDED type, and an unannotated `vec!` of
// struct literals records none, so the element defaulted to SCALAR and `p` bound to the slot ADDRESS instead of
// to the element. Measured: annotating the let, returning the Vec from a fn, or building it with Vec::new() +
// push all produce the correct 10, and only the unannotated literal form fails -- so this is CT-140's Defect A,
// and it is worth THREE of the fourteen known-open witnesses (v_mac, i_struct, i_struct_nomatch).
//
// CT-140 tried to fix Defect A by writing the element type into s9_init_ty and that broke the S9 SELF-HOST
// (gen2 != gen1, five gates): that string has at least two independent consumers. This routes around the shared
// surface entirely rather than reopening it. The loop body is already in hand here, and it says what the element
// is: if the body reads a FIELD off the loop variable, the element is an aggregate, because a scalar has no
// fields. No registry write, no `let`-site change, and nothing else can consume the inference.
// L6's parser accepts `&*x` (used freely above) but DRIFTS on `&**x` -- measured this rung: the first version
// of the two helpers below matched on `&**e` and `&**sc`, and L6 stopped at `for e in init.iter() {` with
// `parse drift`, not a move error. Taking the deref at a CALL boundary instead keeps both tiers happy.
fn s9_is_path_named(e: &ExprK, nm: &str) -> bool { match e { ExprK::Path(pp) => streq(&dump_path(pp), nm), _ => false } }
fn s9_body_reads_field(b: &Block, nm: &str) -> bool {
    if nm.len() == 0 { return false; }
    let mut hit = false;
    for st in b.stmts.iter() { if s9_stmt_reads_field(st, nm) { hit = true; } }
    // The field is often read off a REBINDING of the loop variable rather than off the variable: `let q = p;`
    // then `q.v`, or `match p { q => q.v }`. Both appear in the witness set (i_struct binds through a match arm),
    // and missing them left the inference two-thirds right, which is worse than obviously wrong.
    for st in b.stmts.iter() {
        match st { Stmt::Let(p, _t, init, _e) => { match init { Some(e) => {
                    if s9_is_path_named(e, nm) { let an = s9_patname(p); if an.len() > 0 && s9_body_reads_field(b, &an) { hit = true; } } }, None => {} } }, _ => {} }
    }
    hit
}
fn s9_stmt_reads_field(st: &Stmt, nm: &str) -> bool {
    match st { Stmt::Let(_p, _t, init, _e) => { let mut r = false; match init { Some(e) => { if s9_expr_reads_field(e, nm) { r = true; } }, None => {} } r },
        Stmt::Expr(e) => s9_expr_reads_field(e, nm), Stmt::Semi(e) => s9_expr_reads_field(e, nm), _ => false }
}
fn s9_expr_reads_field(e: &ExprK, nm: &str) -> bool {
    match e {
        ExprK::Field(o, _f) => { if s9_is_path_named(o, nm) { true } else { s9_expr_reads_field(o, nm) } }
        ExprK::Bin(_op, a, b) => s9_expr_reads_field(a, nm) || s9_expr_reads_field(b, nm),
        ExprK::Assign(a, b) => s9_expr_reads_field(a, nm) || s9_expr_reads_field(b, nm),
        ExprK::AssignOp(_op, a, b) => s9_expr_reads_field(a, nm) || s9_expr_reads_field(b, nm),
        ExprK::Unary(_op, a) => s9_expr_reads_field(a, nm),
        ExprK::Paren(a) => s9_expr_reads_field(a, nm),
        ExprK::Method(r, _m, _t, args) => { let mut x = s9_expr_reads_field(r, nm); for a in args.iter() { if s9_expr_reads_field(a, nm) { x = true; } } x }
        ExprK::Call(_c, args) => { let mut x = false; for a in args.iter() { if s9_expr_reads_field(a, nm) { x = true; } } x }
        ExprK::MacCall(_p, _t, _a) => false,
        ExprK::Match(sc, arms) => { let mut x = s9_expr_reads_field(sc, nm);
            for a in arms.iter() {
                if s9_expr_reads_field(&a.body, nm) { x = true; }
                if s9_is_path_named(sc, nm) { let an = s9_patname(&a.pat); if an.len() > 0 && s9_expr_reads_field(&a.body, &an) { x = true; } } }
            x }
        ExprK::ForLoop(_l, _p, it, bb) => { s9_expr_reads_field(it, nm) || s9_body_reads_field(bb, nm) }
        ExprK::While(_l, c, bb) => { s9_expr_reads_field(c, nm) || s9_body_reads_field(bb, nm) }
        ExprK::Block(bb) => s9_body_reads_field(bb, nm),
        ExprK::If(c, t, els) => { let mut x = s9_expr_reads_field(c, nm); if s9_body_reads_field(t, nm) { x = true; } for q in els.iter() { if s9_expr_reads_field(q, nm) { x = true; } } x }
        _ => false
    }
}
fn s9_for_enum(pat: &Pat, itc: &ExprK, body: &Block, env: &S9Env) -> i32 {
    match itc { ExprK::Method(recv, n, _t, a) => { if streq(n, "iter") { if a.len() == 0 {
        let iname = s9_pat_nth_bind(pat, 0);
        let xname = s9_pat_nth_bind(pat, 1);
        let vty = s9_recv_vty(env, recv);
        let ek = s9_vec_elem_kind(&vty);
        let vbase = s9expr(recv, env);
        let it = s9_vec_iter_bounds(vbase);
        let esl = s9fresh(); s9emit_setslot(esl, it.dptr);
        let evl = s9fresh(); s9emit_setslot(evl, esl);
        let icnt = s9fresh(); let z = s9const(0); s9emit_setslot(icnt, z);
        let ib = s9_iter_bind(ek, esl, evl);
        let es = s9_struct_of_ty(&vty);
        let xty = if ib.refty != 0 { if streq(&es, "Vec") || es.len() == 0 { String::from("Ty Ref") } else { format!("Ty Ref(Ty Path {})", es) } } else { String::from("iterscalar") };
        let mut bn: Vec<String> = veccopy(&env.names); bn.push(iname); bn.push(xname);
        let mut bs: Vec<i32> = veccopy_i32(&env.slots); bs.push(icnt); bs.push(ib.slot);
        let mut bt: Vec<String> = veccopy(&env.types); bt.push(String::from("")); bt.push(xty);
        let benv = S9Env { names: bn, slots: bs, fnames: veccopy(&env.fnames), foffs: veccopy_i32(&env.foffs), ftypes: veccopy(&env.ftypes), frets_name: veccopy(&env.frets_name), frets_ty: veccopy(&env.frets_ty), types: bt };
        s9emit_loop_open();
        let g = s9op("lt8", esl, it.end); s9emit_brz(g);
        let ev = s9_slot_load(esl, 0); s9emit_setslot(evl, ev);
        s9_walk(body, &benv);
        s9emit_cont();
        s9emit_incr(icnt);
        s9emit_incr4(esl);
        s9emit_jmpend();
        return s9const(0);
    } }
    // `for (i, c) in s.chars().enumerate()`: enumeration counter i (0,1,2,..) + the char. ASCII char model, so
    // the counter also equals the byte position; kept as its own counter to match enumerate semantics exactly.
    if streq(n, "chars") { if a.len() == 0 {
        let iname = s9_pat_nth_bind(pat, 0);
        let cname = s9_pat_nth_bind(pat, 1);
        let cs = s9expr(recv, env);
        let cb = s9_chars_new(cs, env);
        let icnt = s9fresh(); let z0 = s9const(0); s9emit_setslot(icnt, z0);
        let chsl = s9fresh(); let z1 = s9const(0); s9emit_setslot(chsl, z1);
        let mut bn: Vec<String> = veccopy(&env.names); bn.push(iname); bn.push(cname);
        let mut bs: Vec<i32> = veccopy_i32(&env.slots); bs.push(icnt); bs.push(chsl);
        let mut bt: Vec<String> = veccopy(&env.types); bt.push(String::from("")); bt.push(String::from("char"));
        let benv = S9Env { names: bn, slots: bs, fnames: veccopy(&env.fnames), foffs: veccopy_i32(&env.foffs), ftypes: veccopy(&env.ftypes), frets_name: veccopy(&env.frets_name), frets_ty: veccopy(&env.frets_ty), types: bt };
        s9emit_loop_open();
        let pos = s9_load_at(cb, 16); let len = s9_load_at(cb, 8);
        let g = s9op("lt", pos, len); s9emit_brz(g);
        let dp = s9_slot_load(cb, 0); let a0 = s9op("add8", dp, pos); let b0 = s9_loadb(a0);
        let packed = s9_utf8_decode(dp, pos, b0);
        let mask = s9const(16777215); let cp = s9op("and", packed, mask);
        s9emit_setslot(chsl, cp);
        let s24 = s9const(24); let clen = s9op("shu8", packed, s24); let np = s9op("add", pos, clen); s9_store_at(cb, 16, np);
        s9_walk(body, &benv);
        s9emit_cont();
        s9emit_incr(icnt);
        s9emit_jmpend();
        return s9const(0);
    } }
    s9const(0) }, _ => s9const(0) }
}
fn s9_iter_is_byte(vty: &str) -> bool { if streq(vty, "bytes") { return true; } let e = index_elem(vty); streq(&e, "u8") }   // RP-STD-BYTEITER: a &[u8]/Vec<u8> element is 1 byte -> byte-load + stride-1 iteration
fn s9_for_iter(pat: &Pat, recv: &ExprK, body: &Block, env: &S9Env, byval: bool) -> i32 {
    let vty = s9_recv_vty(env, recv);
    let inm = s9_patname(pat);
    // A method returning a container of REFERENCES (`fn edges(&self) -> Edges<'a, &'a Edge>` = Cow<[&Edge]>) yields
    // `&&T`: the collected Vec holds element pointers (s9_chain_loop tk=6 copies each &Edge), so the loop must bind the LOADED pointer
    // (evl, aggregate) -- NOT the slot address -- so a consumer `f(e)` single-derefs to the struct. The `Ty Ref(` in
    // the method's element type is the marker; a value container (nodes() -> Nodes<'a, Node>) has no ref and stays scalar.
    let mret = match recv { ExprK::Method(_r9, mn9, _t9, _a9) => s9_fn_ret_type(env, mn9), _ => String::new() };
    let ek = if vty.len() == 0 { if str_contains(&mret, "Ty Ref(") { 0 } else if s9_body_reads_field(body, &inm) { 0 } else { s9_vec_elem_kind(&vty) } } else { s9_vec_elem_kind(&vty) };
    let vbase = s9expr(recv, env);
    let it = s9_vec_iter_bounds(vbase);
    let esl = s9fresh(); s9emit_setslot(esl, it.dptr);
    let evl = s9fresh(); s9emit_setslot(evl, esl);
    let ib = s9_iter_bind(ek, esl, evl);
    // `into_iter()` yields each element BY VALUE == `for &q in v.iter()`, so a plain binding `q` gets the value
    // (the slot content), not its address. effref folds byval into the ref-pattern path that already binds evl.
    let isref = s9_pat_is_ref(pat) || byval;
    let bslot = if isref && ek == 1 { evl } else { ib.slot };
    let nm = s9_patname(pat);
    let mut bn: Vec<String> = veccopy(&env.names); bn.push(nm);
    let mut bs: Vec<i32> = veccopy_i32(&env.slots); bs.push(bslot);
    // SR-2: for a USER-struct element, record the FULL element type "Ty Ref(Ty Path Struct)" so `f.field` in the body qualifies
    // by the element struct (C-G2D-FIELD-COLLISION); String/Vec/str/scalar elements keep the plain "Ty Ref"/"" (unchanged dispatch).
    let es = s9_struct_of_ty(&vty);
    let etystr = if isref && ek == 1 { String::from("") } else { if ib.refty != 0 { if streq(&es, "Vec") || es.len() == 0 { String::from("Ty Ref") } else { format!("Ty Ref(Ty Path {})", es) } } else { String::from("iterscalar") } };   // C-S9-ITER-SCALAR-NO-AUTODEREF: mark it so arithmetic can load through it   // C-G2D-STR-VEC-ELEM-TY: a String/str element now records "Ty Ref(Ty Path String)"/"...str" (was bare "Ty Ref", which the format!/{} classifier missed -> a Vec<String> element like a MacCall tok printed as its ADDRESS via __pi). Vec/empty stay bare "Ty Ref" (unchanged dispatch).
    let mut bt: Vec<String> = veccopy(&env.types); bt.push(etystr);
    let benv = S9Env { names: bn, slots: bs, fnames: veccopy(&env.fnames), foffs: veccopy_i32(&env.foffs), ftypes: veccopy(&env.ftypes), frets_name: veccopy(&env.frets_name), frets_ty: veccopy(&env.frets_ty), types: bt };
    if s9_iter_is_byte(&vty) {
        let blen = s9_load_at(vbase, 0); let bend = s9op("add8", it.dptr, blen);
        s9emit_loop_open();
        let g = s9op("lt8", esl, bend); s9emit_brz(g);
        let ev = s9_loadb(esl); s9emit_setslot(evl, ev);
        s9_walk(body, &benv);
        s9emit_cont();
        s9emit_incr(esl);
        s9emit_jmpend();
        return s9const(0);
    }
    s9emit_loop_open();
    let g = s9op("lt8", esl, it.end); s9emit_brz(g);
    let ev = s9_slot_load(esl, 0); s9emit_setslot(evl, ev);
    s9_walk(body, &benv);
    s9emit_cont();
    s9emit_incr4(esl);
    s9emit_jmpend();
    s9const(0)
}
// match arm tail: write the arm body value into the reserved result slot rv (or-merge), jump to the shared merge label.
fn s9emit_arm_tail(rv: i32, lbl: i32, bodyval: i32) { s9ck_reset(); println!("  v{}: i64 = or8 v{} v{}", rv, bodyval, bodyval); println!("  goto __Lm{}", lbl); }
fn s9emit_match_label(lbl: i32) { println!("  label __Lm{}", lbl); s9ck_reset(); }
// `match X { pat => body, .. }` (P-LC-MATCH B5): lower the scrutinee to slot sv; per arm a guard test (integer literal
// pat -> eq sv lit + brz; wildcard/binding -> irrefutable, no test) then body -> or into the reserved result slot rv +
// goto the shared merge label; a refutable arm closes with pool. rv doubles as the merge label id (per B1). Pattern is
// classified INLINE (S9-F11: never pass a matched pat/field to a helper). Payload/tuple/struct destructure + ranges +
// ident-binding-into-body-env are B6/D-tier, deferred.
// is this arm's pattern an integer LITERAL (a refutable eq-test)? classified through a &Pat param (matched directly --
// NOT `&*box_field`, which L6 mis-compiles to a runtime crash, S9-F12). `&**litbox` on a &Box IS the sound codebase idiom.
// the last `::`-segment of a path string (E::A -> A); and whether a path is qualified (contains `::`).
fn s9_last_seg_str(s: &str) -> String { let b = s.as_bytes(); let mut cut = 0; let mut i = 0; while i + 1 < b.len() { if b[i] == 58 { if b[i+1] == 58 { cut = i + 2; } } i += 1; } format!("{}", &s[cut..]) }
fn s9_qualified(s: &str) -> bool { let b = s.as_bytes(); let mut i = 0; let mut q = false; while i + 1 < b.len() { if b[i] == 58 { if b[i+1] == 58 { q = true; } } i += 1; } q }
// pattern classification (via &Pat params, S9-F12): kind 0 = irrefutable (ident/wild), 1 = int literal, 2 = variant
// tuple-struct (E::A(v), has payload binding), 3 = variant path (E::B, unit). test-val = the lit (kind 1) or the variant
