            let vn = s9_last_seg_str(&dump_path(pb));
            if s9_qualified(&dump_path(pb)) { let tag = s9_slot_load(v, 0); let want = s9const(s9_pat_test_val(env, pat) as i64); let c = s9op("eq", tag, want); s9_sc_test(c, mode); }
