// a single OR-alternative's equality condition (for a lit alt) as a value (no brz).
fn s9_test_or1(sp: &Pat, v: i32, env: &S9Env) -> i32 {
    match sp { Pat::Lit(litbox) => { let lv = s9const(s9_litexpr_val(litbox) as i64); s9op("eq", v, lv) }, _ => { let z = s9const(0); z } }
}
fn s9_deep_bind(pat: &Pat, base: i32, byref: bool, env: &S9Env) -> S9Env {
    let mut names = veccopy(&env.names); let mut slots = veccopy_i32(&env.slots); let mut btypes = veccopy(&env.types);
    let cnt = s9_pat_leafn(pat); let mut i = 0;
    while i < cnt { let nm = s9_leaf_name(pat, i); if nm.len() > 0 { let vv = s9_leaf_val(pat, i, base, byref, env); names.push(nm); slots.push(vv); if byref { btypes.push(String::from("Ty Ref i64")); } else { btypes.push(String::from("i64")); } } i = i + 1; }
    S9Env { names: names, slots: slots, fnames: veccopy(&env.fnames), foffs: veccopy_i32(&env.foffs), ftypes: veccopy(&env.ftypes), frets_name: veccopy(&env.frets_name), frets_ty: veccopy(&env.frets_ty), types: btypes }
}
fn s9_arm_bind_off(pat: &Pat) -> i32 { match pat { Pat::Tuple(_ps) => 0, Pat::Slice(_ps) => 0, _ => 8 } }
fn s9_arm_bind_base(b: i32, pat: &Pat) -> i32 { match pat { Pat::Slice(_ps) => s9_slot_load(b, 8), _ => b } }
