    let k0 = if obk == 1 { 2 } else { info.s0 };
    if info.n0.len() > 0 { names.push(format!("{}", info.n0)); slots.push(if info.pst == 1 { s9_fld_load2(sc.base, info.p0, info.q0) } else { if info.ti0 >= 0 { s9_fld_load2(sc.base, info.boff, info.ti0) } else { s9_bind_slot(sc.base, sc.refm, info.boff, k0) } }); let t0 = s9_variant_field_ty(env, vn, 0); if t0.len() > 0 { btypes.push(t0); } else { btypes.push(format!("{}", spty)); } }
