    if info.n2.len() > 0 { names.push(format!("{}", info.n2)); slots.push(if info.pst == 1 { s9_fld_load2(sc.base, info.p2, info.q2) } else { if info.ti2 >= 0 { s9_fld_load2(sc.base, info.boff + 16, info.ti2) } else { s9_bind_slot(sc.base, sc.refm, info.boff + 16, info.s2) } }); btypes.push(s9_variant_field_ty(env, vn, 2)); }
