    // lexer's `chars.next().ok_or(EscapeError::..)?` is exactly this shape).
    match inner { ExprK::Method(_r, m, _t, _a) => { if streq(m, "ok_or") || streq(m, "ok_or_else") || streq(m, "write_all") { return 0; } }, _ => {} }
