    let mlbl = s9_lbl();
    let base = s9expr(scrut, env);
    let mut is_enum = false;
    for arm in arms.iter() { if s9_arm_is_enumish(&arm.pat) || s9_ident_uvariant_tag(env, &arm.pat) >= 0 { is_enum = true; } }
    let by_ref = s9_scrut_by_ref(scrut, env);
