fn s9_first_seg_of_expr(e: &ExprK) -> String { let pn = match e { ExprK::Path(pb) => dump_path(pb), ExprK::Call(cb, _a) => s9_callee_name(cb), _ => String::from("") }; if s9_qualified(&pn) { s9_enum_seg(&pn) } else { String::from("") } }
