        if str_contains(&et, "String") || str_contains(&et, "Vec") { return String::from("Vec<Ty Path String>"); }
        if str_contains(&et, "Ty Path") { return format!("Vec<{}>", et); }
        if s9_is_enum_expr(env, x) { let en = s9_first_seg_of_expr(x); if en.len() > 0 { return format!("Vec<Ty Path {}>", en); } }
