// is this expr a range `a..b` (for slice-index detection)? &ExprK param so a &Box<ExprK> idx auto-derefs (like s9_index).
fn is_range_expr(e: &ExprK) -> bool { match e { ExprK::Range(_a, _b, _i) => true, _ => false } }
