                    let mut sn = String::new(); let mut isint = false;
                    match &fe { ExprK::Struct(sp, _f, _r) => { sn = s9_last_seg_str(&dump_path(sp)); },
                                ExprK::LitInt(_n) => { isint = true; }, _ => {} }
                    if sn.len() > 0 && s9_dbg_is_struct(env, &sn) { return format!("Ty Path Vec<Ty Path {}>", sn); }
