// the offset of field `fname` on struct `sname` (qualified `sname#fname` when registered, else the bare fallback).
fn s9_field_off_q(env: &S9Env, sname: &str, fname: &str) -> i32 { if sname.len() > 0 { let qk = format!("{}#{}", sname, fname); if s9_field_has(env, &qk) { return s9_field_off(env, &qk); } } if !s9_field_has(env, fname) { if streq(fname, "end") { return 8; } if streq(fname, "start") { return 0; } } s9_field_off(env, fname) }
