fn s9_enum_seg(s: &str) -> String { let b = s.as_bytes(); let mut last = 0; let mut prev = 0; let mut i = 0; while i + 1 < b.len() { if b[i] == 58 && b[i+1] == 58 { prev = last; last = i + 2; } i += 1; } if last == 0 { return String::from(""); } format!("{}", &s[prev..(last - 2)]) }
