// The guards live HERE, not in the caller, so the returned count is used exactly ONCE downstream. Written the
// other way -- `let n = s9_repeat_count(..)` followed by two range checks and a call -- L6 rejected the file with
// `use of moved value` and truncated its emission at 178,357 rzir lines, stopping inside `s9_repeat`. The
// boundary is narrower than "an i32 used twice": the `vec!` path does `let n = s9_litexpr_val(&ce); if n > 4096`
// and compiles, so TWO uses are fine and THREE are not. Keeping the producer responsible for validity is the
// shape that avoids having to know exactly where the line is.
// Returns the STATIC count, or -1 when there is none. It no longer refuses: a count that is not a literal or
// a registered const is now lowered at runtime instead (CT-11), so "unresolvable" is a routing decision here
// rather than a failure. The > 4096 cap still applies to the UNROLL path only -- the runtime path has no cap
// because it emits a loop rather than n stores.
fn s9_repeat_count(ce: &ExprK, env: &S9Env) -> i64 {
    let mut c: i64 = 0 - 1;
    if s9_litexpr_kind(ce) == 1 { c = s9_litexpr_val(ce) as i64; }
    else { let nm = s9_bare_name(ce); if nm.len() > 0 { let key = format!("$c#{}", nm); if s9_field_has(env, &key) { c = s9_field_off(env, &key) as i64; } } }
    if c > 4096 { return 0 - 1; }
    c
}
// The element is evaluated ONCE and its slot stored n times, which is Rust's own rule for `[x; n]` -- the value
// is copied, not the expression re-run. That also avoids cloning AST nodes, which this file has no helper for.
// The body deliberately mirrors s9_array's, which is known to compile on this tier.
// The static/runtime branch lives one frame down: with the count bound here, tested, and then passed on, it is
// a call result used twice ACROSS an early return, and L6 rejects the file with `use of moved value` and stops
// emitting inside this function (gen1 came out 1.70MB instead of 2.77MB). As a PARAMETER it is unrestricted.
// Fourth occurrence of C-L6-CALLRESULT-3USE; the recorded rule named the fix before it was tested each time.
fn s9_repeat(elem: &ExprK, count: &ExprK, env: &S9Env) -> i32 {
    let n = s9_repeat_count(count, env);
    s9_repeat_pick(elem, count, env, n)
}
fn s9_repeat_pick(elem: &ExprK, count: &ExprK, env: &S9Env, n: i64) -> i32 {
    if n < 0 { return s9_repeat_rt(elem, count, env); }
    let v = s9expr(elem, env);
    s9_repeat_fill(v, n)
}
fn s9_repeat_rt(elem: &ExprK, count: &ExprK, env: &S9Env) -> i32 {
    let cntv = s9expr(count, env);
    let v = s9expr(elem, env);
    s9_repeat_fill_dyn(v, cntv)
}
// `v` crosses a PARAMETER boundary here. It is a call result reused inside a loop, which is the shape the
// sharpened L6 landmine forbids (an i32 call result passed to more than one call); as a parameter it is
// unrestricted, exactly as s9_vec_iter_bounds' base is. Measured: written inline, L6 rejected the whole file
// with `use of moved value` and truncated its emission to 178,357 rzir lines.
// CT-11 / P-VECMAC-DYN: a repeat whose count is only known at RUNTIME. s9_repeat_fill below is a COMPILE-TIME
// unroll -- its `while i < cnt` runs inside the compiler and emits cnt stores -- so it cannot serve a count
// that is a local, a param or a field, which is 22 of the 24 sites measured in the refusing files.
// Allocation with a runtime size: identical to s9_alloc except the bump is a vreg rather than a const.
fn s9_alloc_dyn(szv: i32) -> i32 {
    let cur = s9_gcur();
    let off = s9fresh(); println!("  v{}: i64 = load8 v{}", off, cur);
    let hb = s9_gheap();
    let base = s9fresh(); println!("  v{}: i64 = add8 v{} v{}", base, hb, off);
    let nc = s9fresh(); println!("  v{}: i64 = add8 v{} v{}", nc, off, szv);
    println!("  store8 v{} v{}", cur, nc);
    base
}
// The emitted fill loop, in the `or`/`or8` slot-reuse shape the hand-written __scat_at/__print_str_at runtime
// helpers already witness: a cursor and a countdown, both rebound through `or` each iteration.
fn s9_fill_loop(buf: i32, cntv: i32, v: i32) {
    let p = s9fresh(); println!("  v{}: i32 = or v{} v{}", p, buf, buf);
    let i = s9fresh(); println!("  v{}: i32 = or v{} v{}", i, cntv, cntv);
    s9emit_loop_open();
    let z = s9const(0);
    let more = s9op("gt", i, z);
    s9emit_brz(more);
    println!("  store8 v{} v{}", p, v);
    let eight = s9const(8);
    let np = s9fresh(); println!("  v{}: i64 = add8 v{} v{}", np, p, eight);
    println!("  v{}: i32 = or v{} v{}", p, np, np);
    let one = s9const(1);
    let ni = s9fresh(); println!("  v{}: i64 = sub8 v{} v{}", ni, i, one);
    println!("  v{}: i32 = or v{} v{}", i, ni, ni);
    s9emit_loop_close();
}
fn s9_repeat_fill_dyn(v: i32, cntv: i32) -> i32 {
    let hdr = s9_alloc(16);
    let eight = s9const(8);
    let bytes = s9op("mul", cntv, eight);
    let buf = s9_alloc_dyn(bytes);
    s9_store_at(hdr, 0, cntv);
    s9_store_at(hdr, 4, cntv);
    s9_slot_store(hdr, 8, buf);
    s9_fill_loop(buf, cntv, v);
    hdr
}
fn s9_repeat_fill(v: i32, n: i64) -> i32 {
    let cnt = n as i32;
    let hdr = s9_alloc(16);
    let buf = s9_alloc(cnt * 8);
    let lenc = s9const(n); s9_store_at(hdr, 0, lenc);
    let capc = s9const(n); s9_store_at(hdr, 4, capc);
    s9_slot_store(hdr, 8, buf);
    let mut off = 0;
    let mut i = 0;
    while i < cnt { s9_slot_store(buf, off, v); off += 8; i += 1; }
    hdr
}
fn s9_array_bytes(elems: &Vec<ExprK>, env: &S9Env) -> i32 {
    // `let x: [u8; N] = [a, b, ..]` -- store PACKED bytes (1/elem) matching the byte-INDEX path (s9_index_byte)
    // and the Vec<u8>/repeat representation. s9_array's default word-per-elem store left b[1..] reading the high
    // bytes of the first word (b[0] ok, b[1..]==0). Only reached for a [u8;N]-annotated array LITERAL.
    let mut n = 0; for _e in elems.iter() { n += 1; }
    let hdr = s9_alloc(16);
    let bw = (n + 7) / 8; let buf = s9_alloc(bw * 8);
    let lenc = s9const(n as i64); s9_store_at(hdr, 0, lenc);
    let capc = s9const(n as i64); s9_store_at(hdr, 4, capc);
    s9_slot_store(hdr, 8, buf);
    let mut off = 0;
    for e in elems.iter() { let sv = s9expr(e, env); let ad = s9op("add", buf, s9const(off as i64)); println!("  storeb v{} v{}", ad, sv); off += 1; }
    hdr
}
// P128-1 (128bit-int sub-arc): a u128/i128 value is a pointer to a {lo@0, hi@8} 16-byte cell (C-128-1).
// s9_box_i128 boxes a scalar into a cell: lo=v (u128 LitInt <= i64::MAX so high is clean-zero), hi=sign-fill
// (sar 63) for i128 else 0. Computed branch-free (dead shr for u128) to keep the emit shape simple.
fn s9_box_i128(v: i32, signed: bool) -> i32 {
    let cell = s9_alloc(16);
    s9_slot_store(cell, 0, v);
    let c63 = s9const(63); let sh = s9op("shr8", v, c63); let z = s9const(0);
    let hi = if signed { sh } else { z };
    s9_slot_store(cell, 8, hi);
    cell
}
// P128-3 (128bit-int): binop dispatch for u128/i128. s9_is_128_expr detects a 128-typed operand; s9_128_val
// yields its {lo,hi} cell (boxing a scalar literal operand). s9_bin128 routes to FR runtime helpers. Kept FLAT
// (no let-in-if tails, minimal fns) per the P128-1 scale-emit-shape lesson; all arithmetic is in FR.
fn s9_is_128_expr(env: &S9Env, e: &ExprK) -> bool {
    let t = s9_lookup_type(env, &s9_bare_name(e)); if str_contains(&t, "128") { return true; }
    let it = s9_init_ty(env, e); str_contains(&it, "128")
}
fn s9_128_val(e: &ExprK, env: &S9Env) -> i32 {
    if s9_is_128_expr(env, e) { return s9expr(e, env); }
    let v = s9expr(e, env); s9_box_i128(v, false)
}
fn s9_bin128(op: &str, a: &ExprK, b: &ExprK, env: &S9Env) -> i32 {
    if streq(op, "Shl") { let va = s9_128_val(a, env); let amt = s9_arith_val(b, env); return s9call2("__u128_shl", va, amt); }
    if streq(op, "Shr") { let va = s9_128_val(a, env); let amt = s9_arith_val(b, env); let ta = s9_lookup_type(env, &s9_bare_name(a)); if str_contains(&ta, "i128") { return s9call2("__i128_sar", va, amt); } return s9call2("__u128_shr", va, amt); }
    let va = s9_128_val(a, env); let vb = s9_128_val(b, env);
    if streq(op, "BitAnd") { return s9call2("__u128_and", va, vb); }
    if streq(op, "BitOr") { return s9call2("__u128_or", va, vb); }
    if streq(op, "BitXor") { return s9call2("__u128_xor", va, vb); }
    if streq(op, "Add") { return s9call2("__u128_add", va, vb); }
    if streq(op, "Sub") { return s9call2("__u128_sub", va, vb); }
    if streq(op, "Mul") { return s9call2("__u128_mul", va, vb); }
    if streq(op, "Div") { return s9call2("__u128_div", va, vb); }
    if streq(op, "Rem") { return s9call2("__u128_mod", va, vb); }
    if streq(op, "Eq") { return s9call2("__u128_eq", va, vb); }
    if streq(op, "Ne") { let e = s9call2("__u128_eq", va, vb); let one = s9const(1); return s9op("sub", one, e); }
    let ta = s9_lookup_type(env, &s9_bare_name(a)); let tb = s9_lookup_type(env, &s9_bare_name(b));
    let sg = str_contains(&ta, "i128") || str_contains(&tb, "i128");
    let lt = if sg { String::from("__i128_lt") } else { String::from("__u128_lt") };
    if streq(op, "Lt") { return s9call2(&lt, va, vb); }
    if streq(op, "Gt") { return s9call2(&lt, vb, va); }
    if streq(op, "Ge") { let g = s9call2(&lt, va, vb); let one = s9const(1); return s9op("sub", one, g); }
    if streq(op, "Le") { let g = s9call2(&lt, vb, va); let one = s9const(1); return s9op("sub", one, g); }
    s9call2("__u128_xor", va, vb)
}
fn s9_let_init(e: &ExprK, annty: &str, env: &S9Env) -> i32 {
    // route a `[u8;N]`-annotated array literal to the byte-packed emitter; everything else is plain s9expr.
    match e { ExprK::Array(elems) => { if str_contains(annty, "Ty Array") && str_contains(annty, "u8") && str_contains(annty, "Vec") == false { return s9_array_bytes(elems, env); } } _ => {} }
    let a128 = str_contains(annty, "u128") || str_contains(annty, "i128");
    if a128 { let it = s9_init_ty(env, e); if !str_contains(&it, "128") { let v = s9expr(e, env); return s9_box_i128(v, str_contains(annty, "i128")); } }
    s9expr(e, env)
}
fn s9_array(elems: &Vec<ExprK>, env: &S9Env) -> i32 {
    let mut slots: Vec<i32> = Vec::new(); let mut n = 0;
    for e in elems.iter() { let s = s9expr(e, env); slots.push(s); n += 1; }
    let hdr = s9_alloc(16);
    let buf = s9_alloc(n * 8);
    let lenc = s9const(n as i64); s9_store_at(hdr, 0, lenc);
    let capc = s9const(n as i64); s9_store_at(hdr, 4, capc);
    s9_slot_store(hdr, 8, buf);
    let mut off = 0;
    for s in slots.iter() { s9_slot_store(buf, off, *s); off += 8; }
    hdr
}
// Vec::new() (E1-GROW/SR-5): a growable Vec = a 3-word header [len=0@0, cap@4, dataptr@8]; value = the header address
// (STABLE across grow -- only dataptr moves, so callers holding the Vec value never rebind). Initial cap = 4 (small: most
// Vecs are small; push grows on demand via __vec_grow, which also shrinks per-Vec peak vs the old fixed-64 block).
fn s9_vec_new() -> i32 {
    let hdr = s9_alloc(16);
    let buf = s9_alloc(4 * 8);
    let z = s9const(0); s9_store_at(hdr, 0, z);
    let c = s9const(4); s9_store_at(hdr, 4, c);
    s9_slot_store(hdr, 8, buf);
    hdr
}
// String::new() (E2, DECOUPLED from Vec at E1-GROW): String stays the inline [len@0, bytes@4+] block (its byte accessors
// s9_str_dataend/push_str read base+4 directly); Vec moved to the header model, so String::new gets its own constructor.
// C-G2D-STR-GROW: String is now the SAME growable header as Vec -- [len@0, cap@4, dataptr@8], bytes at dataptr (byte
// stride). Stable header address; only dataptr moves on grow. Was a fixed 256-byte inline block [len@0, bytes@4+] with no
// grow -> any built string >256 bytes overflowed adjacent heap (P25d). Initial cap 256 bytes.
// INITIAL CAP 64, not 256 (2026-08-26). The identical lever was measured on L6 and is recorded in the arena
// oracle: a fixed per-String block out of a no-free BUMP arena is paid in full by every short String, and this
// file is saturated with them. L6 went 4096 -> 64 and its self-emit fell from 1,902,336 to 897,280 kB with a
// byte-identical image. THE SIBLING TIER HAD THE SAME CLASS and it was never checked -- which is exactly what
// substrate-representation-oracle.md exists to prevent. Growth is already handled by __str_grow (cap*2).
fn s9_str_push_byteval(base: i32, v: i32) {
    let ub = s9const(1); let rg = s9fresh(); println!("  v{}: i32 = call __str_grow v{} v{}", rg, base, ub);
    let daddr = s9_str_dataend(base);
    println!("  storeb v{} v{}", daddr, v);
    let curlen = s9_load_at(base, 0); let one = s9const_fresh(1); let nlen = s9op("add", curlen, one); s9_store_at(base, 0, nlen);
}
fn s9_arg_is_char(a: &ExprK) -> bool { match a { ExprK::Char(_c) => true, _ => false } }
fn s9_emit_isws(byte: i32) -> i32 {
    let c32 = s9const(32); let e1 = s9op("eq", byte, c32);
    let c9 = s9const(9); let e2 = s9op("eq", byte, c9);
    let c10 = s9const(10); let e3 = s9op("eq", byte, c10);
    let c13 = s9const(13); let e4 = s9op("eq", byte, c13);
    let o1 = s9op("or", e1, e2); let o2 = s9op("or", e3, e4); s9op("or", o1, o2)
}
fn s9_str_parse(recv: &ExprK, env: &S9Env) -> i32 {
    let src = s9expr(recv, env);
    let slen = s9_load_at(src, 0); let sdp = s9_slot_load(src, 8);
    let first = s9_loadb(sdp);
    let c45 = s9const(45); let isneg = s9op("eq", first, c45);
    let acc = s9fresh(); let z0 = s9const(0); s9emit_setslot(acc, z0);
    let ix = s9fresh(); s9emit_setslot(ix, isneg);
    s9emit_loop_open();
    let g = s9op("lt", ix, slen); s9emit_brz(g);
    let addr = s9op("add8", sdp, ix); let byte = s9_loadb(addr);
    let c48 = s9const(48); let digit = s9op("sub", byte, c48);
    let c10 = s9const(10); let t = s9op("mul8", acc, c10); let nacc = s9op("add8", t, digit); s9emit_setslot(acc, nacc);
    s9emit_cont(); s9emit_incr(ix); s9emit_jmpend();
    let two = s9const(2); let tn = s9op("mul8", two, isneg); let one = s9const(1); let sign = s9op("sub8", one, tn);   // 64-bit: -1 sign-extended (32-bit sub -> 0xFFFFFFFF zero-extends in mul8 -> acc*4294967295)
    let signed = s9op("mul8", acc, sign);
    s9_ok_of(env, signed)
}
fn s9_str_trim(recv: &ExprK, env: &S9Env) -> i32 { s9_str_trim_dir(recv, 1, 1, env) }
// trim family: `left`/`right` select the leading/trailing ASCII-whitespace scans (compile-time flags -> conditional
// emission). trim=(1,1), trim_start=(1,0), trim_end=(0,1). Returns a &str borrow header (len@0, cap=0@4, dptr@8).
fn s9_str_trim_matches_str(recv: &ExprK, arg: &ExprK, left: i32, right: i32, env: &S9Env) -> i32 {
    // trim_*_matches for a &str pattern: repeatedly remove the leading/trailing plen-byte pattern. plen is known at
    // compile time (literal), so the byte compare is unrolled; the outer while is runtime.
    let fs = s9_lit_bytes(arg); let fb = fs.as_bytes(); let plen = fb.len();
    let src = s9expr(recv, env);
    let slen = s9_load_at(src, 0); let sdp = s9_slot_load(src, 8);
    let si = s9fresh(); let z0 = s9const(0); s9emit_setslot(si, z0);
    if left == 1 && plen > 0 {
        s9emit_loop_open();
        let plc = s9const(plen as i64); let idl = s9op("add", si, plc); let mut m = s9op("le", idl, slen);
        let mut k = 0;
        while k < plen {
            let bi0 = s9op("add8", sdp, si); let kc = s9const(k as i64); let baddr = s9op("add", bi0, kc);
            let bk = s9_loadb(baddr); let fbc = s9const(fb[k] as i64); let ek = s9op("eq", bk, fbc);
            m = s9op("and", m, ek); k += 1;
        }
        s9emit_brz(m);
        let plc2 = s9const(plen as i64); let nsi = s9op("add", si, plc2); s9emit_setslot(si, nsi);
        s9emit_cont(); s9emit_jmpend();
    }
    let ej = s9fresh(); s9emit_setslot(ej, slen);
    if right == 1 && plen > 0 {
        s9emit_loop_open();
        let plc = s9const(plen as i64); let estart = s9op("sub", ej, plc); let mut m = s9op("ge", estart, si);
        let mut k = 0;
        while k < plen {
            let bi0 = s9op("add8", sdp, estart); let kc = s9const(k as i64); let baddr = s9op("add", bi0, kc);
            let bk = s9_loadb(baddr); let fbc = s9const(fb[k] as i64); let ek = s9op("eq", bk, fbc);
            m = s9op("and", m, ek); k += 1;
        }
        s9emit_brz(m);
        let plc2 = s9const(plen as i64); let nej = s9op("sub", ej, plc2); s9emit_setslot(ej, nej);
        s9emit_cont(); s9emit_jmpend();
    }
    let newlen = s9op("sub", ej, si);
    let newdp = s9op("add8", sdp, si);
    let hdr = s9_alloc(16); s9_store_at(hdr, 0, newlen); let z1 = s9const(0); s9_store_at(hdr, 4, z1); s9_slot_store(hdr, 8, newdp);
    hdr
}
fn s9_str_trim_matches(recv: &ExprK, arg: &ExprK, left: i32, right: i32, env: &S9Env) -> i32 {
    // trim_start_matches/trim_end_matches/trim_matches for a CHAR pattern: like s9_str_trim_dir but the skip
    // predicate is byte==pattern instead of is-whitespace. Returns a &str borrow header [len,0,dptr].
    let fbs = s9_lit_bytes(arg); let fbb = fbs.as_bytes(); let fcv = if fbb.len() > 0 { fbb[0] as i64 } else { 0 };
    let src = s9expr(recv, env);
    let slen = s9_load_at(src, 0); let sdp = s9_slot_load(src, 8);
    let si = s9fresh(); let z0 = s9const(0); s9emit_setslot(si, z0);
    if left == 1 {
        s9emit_loop_open();
        let c1 = s9op("lt", si, slen);
        let addr1 = s9op("add8", sdp, si); let b1 = s9_loadb(addr1);
        let fc1 = s9const(fcv); let w1 = s9op("eq", b1, fc1);
        let g1 = s9op("and", c1, w1); s9emit_brz(g1);
        s9emit_cont(); s9emit_incr(si); s9emit_jmpend();
    }
    let ej = s9fresh(); s9emit_setslot(ej, slen);
    if right == 1 {
        s9emit_loop_open();
        let c2 = s9op("gt", ej, si);
        let one = s9const(1); let jm1 = s9op("sub", ej, one);
        let addr2 = s9op("add8", sdp, jm1); let b2 = s9_loadb(addr2);
        let fc2 = s9const(fcv); let w2 = s9op("eq", b2, fc2);
        let g2 = s9op("and", c2, w2); s9emit_brz(g2);
        s9emit_cont();
        let one2 = s9const(1); let dec = s9op("sub", ej, one2); s9emit_setslot(ej, dec);
        s9emit_jmpend();
    }
    let newlen = s9op("sub", ej, si);
    let newdp = s9op("add8", sdp, si);
    let hdr = s9_alloc(16); s9_store_at(hdr, 0, newlen); let z1 = s9const(0); s9_store_at(hdr, 4, z1); s9_slot_store(hdr, 8, newdp);
    hdr
}
fn s9_str_trim_dir(recv: &ExprK, left: i32, right: i32, env: &S9Env) -> i32 {
    let src = s9expr(recv, env);
    let slen = s9_load_at(src, 0); let sdp = s9_slot_load(src, 8);
    let si = s9fresh(); let z0 = s9const(0); s9emit_setslot(si, z0);
    if left == 1 {
        s9emit_loop_open();
        let c1 = s9op("lt", si, slen);
        let addr1 = s9op("add8", sdp, si); let b1 = s9_loadb(addr1);
        let w1 = s9_emit_isws(b1);
        let g1 = s9op("and", c1, w1); s9emit_brz(g1);
        s9emit_cont(); s9emit_incr(si); s9emit_jmpend();
    }
    let ej = s9fresh(); s9emit_setslot(ej, slen);
    if right == 1 {
        s9emit_loop_open();
        let c2 = s9op("gt", ej, si);
        let one = s9const(1); let jm1 = s9op("sub", ej, one);
        let addr2 = s9op("add8", sdp, jm1); let b2 = s9_loadb(addr2);
        let w2 = s9_emit_isws(b2);
        let g2 = s9op("and", c2, w2); s9emit_brz(g2);
        s9emit_cont();
        let one2 = s9const(1); let dec = s9op("sub", ej, one2); s9emit_setslot(ej, dec);
        s9emit_jmpend();
    }
    let newlen = s9op("sub", ej, si);
    let newdp = s9op("add8", sdp, si);
    let hdr = s9_alloc(16);
    s9_store_at(hdr, 0, newlen);
    let z1 = s9const(0); s9_store_at(hdr, 4, z1);
    s9_slot_store(hdr, 8, newdp);
    hdr
}
