    let hdr = s9_alloc(16); s9_store_at(hdr, 0, plen); let zc = s9const(0); s9_store_at(hdr, 4, zc); s9_slot_store(hdr, 8, pdp);
    s9_vec_push1(vec, hdr);
    let dlc2 = s9const(dlen as i64); let ni = s9op("add", i, dlc2); s9emit_setslot(start, ni);
    let one1 = s9const(1); let nc = s9op("add", cuts, one1); s9emit_setslot(cuts, nc);
    s9emit_pool();
    let dm1 = s9const((dlen - 1) as i64); let mfl = s9op("mul", m, dm1); let one2 = s9const(1); let adv = s9op("add", mfl, one2);
    s9emit_cont();
    let ia = s9op("add", i, adv); s9emit_setslot(i, ia);
    s9emit_jmpend();
