    let slen2 = s9_load_at(src2, 0); let sdp2 = s9_slot_load(src2, 8);
    let flen = s9op("sub", slen2, start); let fdp = s9op("add8", sdp2, start);
    let fhdr = s9_alloc(16); s9_store_at(fhdr, 0, flen); let zc2 = s9const(0); s9_store_at(fhdr, 4, zc2); s9_slot_store(fhdr, 8, fdp);
