    let vec = s9_vec_new();
    let start = s9fresh(); let z0 = s9const(0); s9emit_setslot(start, z0);
    let i = s9fresh(); let z1 = s9const(0); s9emit_setslot(i, z1);
    s9emit_loop_open();
