    s9emit_pool();
    s9emit_cont();
    let o3 = s9const(1); let ia = s9op("add", i, o3); s9emit_setslot(i, ia);
    s9emit_jmpend();
    let src2 = s9expr(recv, env); let slen2 = s9_load_at(src2, 0); let sdp2 = s9_slot_load(src2, 8);
    let rem = s9op("sub", slen2, start); let zc3 = s9const(0); let has = s9op("gt", rem, zc3);
    s9emit_brz(has);
