    let ub = s9_char_range(bb, 65, 90); let c32b = s9const(32); let db = s9op("mul8", ub, c32b); let fb = s9op("add", bb, db);
    let eqb = s9op("eq", fa, fb); let na = s9op("and", acc, eqb); s9emit_setslot(acc, na);
    let one = s9const(1); let ni = s9op("add", i, one); s9emit_setslot(i, ni);
    s9emit_loop_close();
    s9emit_pool();
