    let fidxcell = s9_alloc(4); let z0 = s9const(0); s9_store_at(fidxcell, 0, z0);
    let seencell = s9_alloc(4); let z1 = s9const(0); s9_store_at(seencell, 0, z1);
    let icell = s9_alloc(4); let z2 = s9const(0); s9_store_at(icell, 0, z2);
