    let oldf = s9_load_at(fidxcell, 0); let one2 = s9const(1); let nsel = s9op("sub", one2, sel);
    let a0 = s9op("mul8", i, sel); let a1 = s9op("mul8", oldf, nsel); let nf = s9op("add8", a0, a1); s9_store_at(fidxcell, 0, nf);
    let newseen = s9op("or", oldseen, m); s9_store_at(seencell, 0, newseen);
