    // 1<<62 built at runtime (shl8): SEM0 cannot carry a 19-digit i64 literal in its own codegen (int-literal
    // range limit), so the constant is emitted as `1 << 62` rather than written directly.
    let bit = s9fresh(); let onv = s9const(1); let s62 = s9const(62); let b0 = s9op("shl8", onv, s62); s9emit_setslot(bit, b0);
