    if str_contains(ty, "u8") || str_contains(ty, "i8") { return 8; }
    if str_contains(ty, "u16") || str_contains(ty, "i16") { return 16; }
    if str_contains(ty, "u32") || str_contains(ty, "i32") { return 32; }
