            // `store` (const packed little-endian, 32-bit, always < 2^31 so cf-safe) -- 1 rzir line/byte vs 4 --
            // with per-byte storeb for the <4 tail and any group with a byte >= 128. store writes 4 bytes LE;
            // packed = dbyte[di] + dbyte[di+1]*256 + dbyte[di+2]*65536 + dbyte[di+3]*16777216 (first byte LSB).
            let mut dbytes: Vec<i64> = Vec::new();
            let mut si = 0;
            while si < cb.len() {
                let mut byte = cb[si] as i64; let mut adv = 1;
                if cb[si] == 92 && si + 1 < cb.len() { let d = s9_esc_byte(cb[si + 1]); if d >= 0 { byte = d; adv = 2; } }
                dbytes.push(byte); si += adv;
            }
            let dn = dbytes.len();
            let mut di = 0;
            while di + 4 <= dn {
                let mut ok = 1; let mut k = 0;
                while k < 4 { if dbytes[di + k] >= 128 { ok = 0; k = 4; } else { k = k + 1; } }
                if ok == 1 {
                    let mut packed = 0; let mut k2 = 4;
                    while k2 > 0 { k2 = k2 - 1; packed = packed * 256 + dbytes[di + k2]; }
                    let ic = s9const(di as i64); let addr = s9op("add", daddr, ic); let pc = s9const(packed); println!("  store v{} v{}", addr, pc);
                    di = di + 4;
                } else {
                    let ic = s9const(di as i64); let addr = s9op("add", daddr, ic); let bc = s9const(dbytes[di]); println!("  storeb v{} v{}", addr, bc);
                    di = di + 1;
                }
            }
            while di < dn {
                let ic = s9const(di as i64); let addr = s9op("add", daddr, ic); let bc = s9const(dbytes[di]); println!("  storeb v{} v{}", addr, bc);
                di = di + 1;
            }
