    // format literal because this returned empty on the produced chain while native was fine). Iterate + flag.
    let mut out: Vec<String> = Vec::new(); let mut depth = 0; let mut seen = false;
    for t in toks.iter() {
        if seen { out.push(format!("{}", t)); }
        else if streq(t, "(") || streq(t, "[") || streq(t, "{") { depth += 1; }
        else if streq(t, ")") || streq(t, "]") || streq(t, "}") { depth -= 1; }
        else if streq(t, ",") && depth == 0 { seen = true; }
    }
    out
