    let e = s9_reparse_expr(&src);
    let cv = s9expr(&e, env);
    let z = s9const(0);
    let nz = s9op("eq", cv, z);
    s9emit_brz(nz);
    s9_abort_emit();
    s9emit_pool();
    s9const(0)
