    let b = s9_vec_seg_src(toks, 1, ",");
    let mut src = String::new();
    src.push_str("(");
    src.push_str(&a);
    src.push_str(") ");
    src.push_str(op);
    src.push_str(" (");
    src.push_str(&b);
    src.push_str(")");
