                   let ta = s9_dbg_arity(&ty, "dbgtup ");
                   if ta > 0 { let tv = s9expr(e, env); s9_dbg_load_seq(tv, ta, 40, false, &ty); return true; }
                   let aa = s9_dbg_arity(&ty, "dbgarr ");
                   if aa > 0 { let av = s9expr(e, env); s9_dbg_load_seq(av, aa, 91, true, &ty); return true; }
                   // A Vec reached through a name: runtime length, so the loop emitter rather than the
                   // fixed-arity one. Gated on the RECORDED type, so an untyped vec is unchanged.
                   // A vec! LITERAL records its element kind; a Vec built by Vec::new() + push has no literal to
                   // read, so the type channel still carries it and defaults to the integer kind. Both reach the
                   // same loop.
                   let vtn = s9_lookup_type(env, &nm);   // top-level named Vec with an AGGREGATE/NESTED element: dispatch each element by type string (s9_dbg_vec2) so Vec<struct>/Vec<Vec<..>> recurse instead of printing addresses. Scalar/str elements stay on the existing path below (driver-unaffected).
                   if s9_dbg_pfx(&vtn, "Ty Path Vec<") { let et = s9_vec_elem_ty(&vtn); let en0 = s9_struct_of_ty(&et); if str_contains(&et, "Vec") || s9_field_has(env, &format!("$nflds#{}", en0)) || s9_field_has(env, &format!("$ust#{}", en0)) || s9_has_variants(env, &en0) { let vv = s9expr(e, env); s9_dbg_vec2(vv, &et, env); return true; } }
                   let vk = s9_dbg_arity(&ty, "dbgvec ");
                   if vk >= 0 { let vv = s9expr(e, env); s9_dbg_vec(vv, vk, "", env); return true; }
