    if sslot >= 0 { let st = s9_self_ty(base); if st.len() > 0 { let sa = s9_self_args(base); let sty = if sa.len() > 0 { format!("Ty Path {}<{}>", st, sa) } else { format!("Ty Path {}", st) }; names.push(String::from("self")); slots.push(sslot); types.push(sty); } }
    // AST2-BYREF: a `&self`/`&mut self` receiver makes bare `self` a REFERENCE, so `match self { V(x) => *x }` must bind
