// firing set is an allowlist of std/core traits rather than a not-found test.
fn is_std_trait(name: &str) -> bool {
    if streq(name, "Clone") { return true; } if streq(name, "Copy") { return true; }
    if streq(name, "Debug") { return true; } if streq(name, "Display") { return true; }
    if streq(name, "Default") { return true; } if streq(name, "Hash") { return true; }
    if streq(name, "PartialEq") { return true; } if streq(name, "Eq") { return true; }
    if streq(name, "PartialOrd") { return true; } if streq(name, "Ord") { return true; }
    if streq(name, "Add") { return true; } if streq(name, "Sub") { return true; }
    if streq(name, "Mul") { return true; } if streq(name, "Div") { return true; }
    if streq(name, "Rem") { return true; } if streq(name, "Neg") { return true; }
    if streq(name, "Not") { return true; } if streq(name, "Iterator") { return true; }
    false
}
